import { useEffect, useState } from "react";
import { Link, useParams } from "react-router-dom";
import { Download } from "lucide-react";
import { toast } from "sonner";
import { api, errMsg, getClientId, exportUrl } from "@/lib/api";
import { dt, price, pct, score, yuan, tclass } from "@/lib/format";
import { Empty, Section, QuoteBadge } from "@/components/common";
import { PageTitle } from "@/components/ResultsShared";

async function downloadCsv() {
  let blob;
  try {
    const r = await fetch(exportUrl(), { headers: { "X-Client-Id": getClientId() } });
    if (!r.ok) throw new Error(`HTTP ${r.status}`);
    blob = await r.blob();
  } catch (e) {
    toast.error(`导出失败：${e.message}`);
    return;
  }
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob);
  a.download = "ashare_history.csv";
  a.click();
}

const Bool = ({ v }) => (v == null ? <span className="text-slate-600">待定</span> : v ? <span className="up">是</span> : <span className="text-slate-400">否</span>);

function ScanDetail({ sid }) {
  const [d, setD] = useState(null);
  const [err, setErr] = useState(null);
  useEffect(() => { api.get(`/history/scans/${sid}`).then((r) => setD(r.data)).catch((e) => setErr(errMsg(e))); }, [sid]);
  if (err) return <Empty title="无法加载" testid="history-detail-error">{err}</Empty>;
  if (!d) return <div className="panel h-60 animate-pulse" />;
  const s = d.session;
  const rows = d.predictions.filter((p) => p.prediction_horizon === s.horizon);
  return (
    <Section testid="history-detail" title={`分析 #${s.id} · ${dt(s.started_at)}`}
      extra={<Link to="/history" className="text-xs text-blue-300" data-testid="history-back">返回列表</Link>}>
      <div className="flex flex-wrap gap-3 text-xs text-slate-400 mb-4">
        <span>行情时间 <b className="font-num text-slate-200">{dt(s.quote_time)}</b></span><span>{s.data_source}</span>
        <span>模型 <b className="font-num text-slate-200">{s.model_version || "无"}</b></span><span>资金 {yuan(s.capital)}</span>
        <span>{s.parsed_preferences?.inputs ? `价格 ${s.parsed_preferences.inputs.price_unlimited ? "不限" : `${s.parsed_preferences.inputs.price_min ?? "—"}–${s.parsed_preferences.inputs.price_max ?? "—"}`} · 计划投入 ${yuan(s.parsed_preferences.inputs.planned_amount)}` : `要求：${s.user_preferences || "默认"}`}</span>
      </div>
      <div className="overflow-x-auto">
        <table className="w-full text-xs min-w-[900px]">
          <thead className="text-slate-500 text-left"><tr>
            <th className="py-2">股票</th><th>候选</th><th>评分</th><th>当时今日区间</th><th>明日区间（{rows[0]?.target_trade_date || "—"}）</th>
            <th>预测收盘区间</th><th>次日实际 低/高/收</th><th>可成交</th><th>成交价</th><th>1日</th><th>3日</th><th>5日</th>
          </tr></thead>
          <tbody>
            {rows.map((p) => (
              <tr key={p.id} className="border-t border-[#1E2838]" data-testid={`history-pred-${p.stock_code}`}>
                <td className="py-2"><Link to={`/stock/${p.stock_code}`} className="hover:text-blue-300">{p.stock_name} <span className="font-num text-sky-400">{p.stock_code}</span></Link></td>
                <td>{p.is_candidate ? <span className="up">候选</span> : <span className="text-slate-500">观察</span>}</td>
                <td className="font-num">{score(p.overall_score)}</td>
                <td className="font-num">{price(p.today_buy_zone_low)}–{price(p.today_buy_zone_high)}</td>
                <td className="font-num">{price(p.buy_zone_low)}–{price(p.buy_zone_high)}</td>
                <td className="font-num">{price(p.predicted_price_low)}–{price(p.predicted_price_high)}</td>
                <td className="font-num">{p.actual_close != null ? `${price(p.actual_low)}/${price(p.actual_high)}/${price(p.actual_close)}` : "待定"}</td>
                <td><Bool v={p.executable} /></td>
                <td className="font-num">{price(p.entry_price)}</td>
                {[1, 3, 5].map((h) => <td key={h} className={`font-num ${tclass(p[`actual_return_${h}d`])}`}>{pct(p[`actual_return_${h}d`], 2, true)}</td>)}
              </tr>
            ))}
          </tbody>
        </table>
        {!rows.length && <p className="text-sm text-slate-400 py-6" data-testid="history-no-preds">本次分析没有保存预测记录（{d.summary?.no_opportunity_message || "无候选"}）。</p>}
      </div>
      <p className="text-[11px] text-slate-500 mt-3">实际表现在后续交易日行情进入本地历史库后自动回填；收益已扣除默认交易成本与滑点，以明日区间上沿为限价判断是否可成交。</p>
    </Section>
  );
}

export default function HistoryPage() {
  const { sid } = useParams();
  const [list, setList] = useState(null);
  useEffect(() => { api.get("/history/scans").then((r) => setList(r.data)).catch(() => setList([])); }, []);
  return (
    <div className="space-y-6" data-testid="history-page">
      <div className="flex flex-wrap items-end justify-between gap-3">
        <PageTitle title="历史记录" sub="每次分析的候选名单、当时的行情时间与模型版本，以及后续真实表现。" />
        <button onClick={downloadCsv} data-testid="export-history-btn" className="text-xs px-3 py-2 rounded-lg border border-[#222D3D] text-slate-300 hover:text-white hover:border-blue-500/50 flex items-center gap-1.5">
          <Download className="w-3.5 h-3.5" /> 导出 CSV
        </button>
      </div>
      {sid ? <ScanDetail sid={sid} /> : !list ? <div className="panel h-40 animate-pulse" /> : !list.length ? (
        <Empty title="暂无历史分析" testid="history-empty">完成一次分析后会自动保存在这里。</Empty>
      ) : (
        <div className="space-y-3" data-testid="history-list">
          {list.map((s) => (
            <Link key={s.id} to={`/history/${s.id}`} data-testid={`history-item-${s.id}`} className="panel p-4 flex flex-wrap items-center gap-x-6 gap-y-2 hover:border-blue-500/40 transition-colors">
              <div className="font-num text-slate-200 text-sm">#{s.id} · {dt(s.started_at)}</div>
              <QuoteBadge type={s.quote_type} label={s.quote_type || s.status} />
              <div className="text-xs text-slate-400">状态 {s.status} · 股票池 {s.universe_size ?? "—"} · 分析 {s.analyzed_count ?? "—"}</div>
              <div className="text-xs text-slate-300">
                候选 <b className="font-num up">{s.candidate_count ?? 0}</b>{s.candidates_brief.length ? `：${s.candidates_brief.map((c) => c.name).join("、")}` : ""}
              </div>
              <div className="text-[11px] text-slate-500 ml-auto">模型 {s.model_version || "无"}</div>
            </Link>
          ))}
        </div>
      )}
    </div>
  );
}
