import { useEffect, useState } from "react";
import { CheckCircle2, XCircle, Download } from "lucide-react";
import { api } from "@/lib/api";
import { pct, dt } from "@/lib/format";
import { Section, Stat } from "@/components/common";
import { CalibrationChart } from "@/charts/Charts";
import { StatusBadge } from "@/components/StrategyStatus";

const HZ = ["1", "3", "5"];
const API = `${process.env.REACT_APP_BACKEND_URL}/api`;
const n4 = (v) => (typeof v === "number" ? v.toFixed(4) : "—");

export const HzTabs = ({ h, setH, list = HZ, prefix }) => (
  <div className="flex gap-2 text-xs">
    {list.map((x) => (
      <button key={x} data-testid={`${prefix}-hz-${x}`} onClick={() => setH(x)}
        className={`px-3 py-1 rounded-full border ${h === x ? "border-red-500/60 text-red-200 bg-red-500/10" : "border-[#222D3D] text-slate-400"}`}>{x} 日</button>
    ))}
  </div>
);

const Check = ({ c }) => (
  <li className="flex items-start gap-2 text-xs py-1 border-t border-[#1E2838]">
    {c.pass ? <CheckCircle2 className="w-4 h-4 text-red-300 shrink-0" /> : <XCircle className="w-4 h-4 text-slate-500 shrink-0" />}
    <span className="flex-1 text-slate-300">{c.name}</span>
    <span className="font-num text-slate-400 text-right">{c.detail || String(c.value ?? "")}</span>
  </li>
);

function KV({ rows }) {
  return (
    <table className="w-full text-xs">
      <tbody>{rows.map(([k, v]) => <tr key={k} className="border-t border-[#1E2838]"><td className="py-1.5 text-slate-500">{k}</td><td className="font-num text-slate-200 text-right">{v}</td></tr>)}</tbody>
    </table>
  );
}

function CalibCompare({ h }) {
  const rows = [["原始分数", h.test_raw], ["Platt（逻辑回归）", h.test_platt], ["Isotonic（保序回归）", h.test_isotonic]].filter(([, m]) => m);
  const cols = [["n", "样本"], ["positive_rate", "正样本"], ["auc", "AUC"], ["brier", "Brier"], ["brier_baseline", "Brier基准"], ["log_loss", "LogLoss"], ["ece", "ECE"], ["slope", "斜率"], ["intercept", "截距"]];
  return (
    <div className="overflow-x-auto">
      <table className="w-full text-xs min-w-[640px]" data-testid="calibration-compare-table">
        <thead className="text-slate-500 text-left"><tr><th className="py-1.5">独立测试集</th>{cols.map(([, l]) => <th key={l}>{l}</th>)}</tr></thead>
        <tbody>{rows.map(([name, m]) => (
          <tr key={name} className="border-t border-[#1E2838]"><td className="py-1.5 text-slate-300">{name}</td>{cols.map(([k]) => <td key={k} className="font-num">{m[k] ?? "—"}</td>)}</tr>
        ))}</tbody>
      </table>
    </div>
  );
}

function Diagnostics({ h }) {
  const conc = h.importance_concentration;
  return (
    <div className="grid md:grid-cols-2 gap-6 text-xs">
      <div>
        <div className="eyebrow mb-2">单特征样本外信息系数（验证期，前 12）</div>
        <KV rows={(h.ic_valid || []).slice(0, 12).map((r) => [r.feature, `IC ${n4(r.ic_mean)} · IR ${r.ic_ir ?? "—"}`])} />
      </div>
      <div>
        <div className="eyebrow mb-2">打乱特征后 AUC 下降（前 12）</div>
        <KV rows={(h.permutation_importance?.items || []).slice(0, 12).map((r) => [r.feature, n4(r.auc_drop)])} />
        {conc && <p className="text-slate-500 mt-2">重要性集中度：前 5 占 {pct(conc.top5_share, 0)}，前 10 占 {pct(conc.top10_share, 0)}，有效特征数约 {conc.effective_features}</p>}
      </div>
      <div>
        <div className="eyebrow mb-2">标签与样本</div>
        <p className="text-slate-400 leading-relaxed">{h.label?.definition}</p>
        <KV rows={[["正/负样本", `${h.label?.positive?.toLocaleString()} / ${h.label?.negative?.toLocaleString()}`], ["正样本比例", pct(h.label?.positive_rate, 1)],
          ...Object.entries(h.class_balance || {}).map(([k, v]) => [`${{ train: "训练", valid: "验证", calib: "校准", test: "测试" }[k]}期正样本比例`, pct(v, 1)])]} />
      </div>
      <div>
        <div className="eyebrow mb-2">板块差异（同日排名标准化前 → 后）</div>
        <KV rows={(h.board_distribution?.dispersion_raw_vs_ranked || []).map((r) => [r.feature, `${r.raw_between_board_spread} → ${r.ranked_between_board_spread}`])} />
      </div>
    </div>
  );
}

export function ModelV2Report() {
  const [r, setR] = useState(null);
  const [h, setH] = useState("5");
  useEffect(() => { api.get("/research/report?kind=model_v2").then((x) => setR(x.data)).catch(() => setR({ available: false })); }, []);
  if (!r) return null;
  if (!r.available) return <Section title="第二版模型诊断与校准" testid="v2-report"><p className="text-sm text-slate-400" data-testid="v2-report-pending">报告尚未生成：后台训练与滚动回测完成后自动出现（{r.job?.message || "未运行"}）。</p></Section>;
  const p = r.payload, x = p.horizons[h], cmp = p.comparison || {}, g = x.probability_gates;
  return (
    <Section title={`第二版模型 ${r.model_version}`} testid="v2-report" extra={<span className={`text-xs ${p.activated ? "text-red-300" : "text-slate-400"}`} data-testid="v2-activated">{p.activated ? "已启用" : "未启用（保留旧版本）"}</span>}>
      <div className="space-y-6">
        <div className="text-xs text-slate-400 space-y-1" data-testid="v2-comparison">
          <div>优化前后对比（同一独立测试集 {cmp.test_period?.join(" ~ ")}）：5 日 AUC 旧 <b className="font-num">{cmp.auc_5d?.old}</b> → 新 <b className="font-num">{cmp.auc_5d?.new}</b>；3 日 AUC 旧 <b className="font-num">{cmp.auc_3d?.old}</b> → 新 <b className="font-num">{cmp.auc_3d?.new}</b></div>
          <div>5 日交易平均净收益：旧 <b className="font-num">{pct(cmp.trades_5d?.old?.mean_net_return, 2)}</b>（{cmp.trades_5d?.old?.trades} 笔）→ 新 <b className="font-num">{pct(cmp.trades_5d?.new?.mean_net_return, 2)}</b>（{cmp.trades_5d?.new?.trades} 笔）</div>
          <div className="text-slate-300">{cmp.reason}</div>
          <div>训练 {p.split.train.join("~")} · 验证 {p.split.valid.join("~")} · 校准 {p.split.calib.join("~")} · 测试 {p.split.test.join("~")} · 泄漏检查 {p.leakage?.pass ? "通过" : "未通过"} · 特征 {p.features.total_used} 个（剔除高相关 {p.features.dropped_correlated.length} 个）</div>
        </div>
        <HzTabs h={h} setH={setH} prefix="v2" />
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
          <Stat label="选用模型" value={x.model_selection.selected} sub="按验证集 AUC 选择" />
          <Stat label="测试 AUC" value={x.test_auc_per_model[x.model_selection.selected] ?? "—"} sub={Object.entries(x.test_auc_per_model).map(([k, v]) => `${k} ${v}`).join(" · ")} />
          <Stat label="校准方法" value={x.calibration.method || "未建立"} sub={x.calibration.built ? `校准样本 ${x.calibration.calib_rows.toLocaleString()}` : x.calibration.reason} />
          <Stat label="概率展示准入" value={g.passed ? "通过" : "未通过"} sub={g.passed ? "显示正收益概率" : "显示模型评分"} testid={`v2-gate-${h}`} />
        </div>
        <CalibCompare h={x} />
        <div className="grid md:grid-cols-2 gap-6">
          <div><div className="eyebrow mb-2">校准曲线（选用方法，测试集）</div><CalibrationChart bins={g.metrics?.curve || x.test_raw?.curve} /></div>
          <div><div className="eyebrow mb-2">准入条件（测试前锁定）</div><ul data-testid="v2-gate-checks">{g.checks.map((c) => <Check key={c.name} c={c} />)}</ul></div>
        </div>
        <Diagnostics h={x} />
      </div>
    </Section>
  );
}

function ControlTable({ x }) {
  const rows = [["系统策略", x.system], ["随机对照（均值）", { trades: x.random.trades?.mean, mean_net_return: x.random.mean_net_return?.mean, win_rate: x.random.win_rate?.mean, max_drawdown: x.random.max_drawdown?.median }],
    ["全市场次日开盘", { trades: x.market.rows, mean_net_return: x.market.mean_net_return, win_rate: x.market.win_rate }], ["RSI 最低 5 只", x.rsi]];
  return (
    <div className="overflow-x-auto">
      <table className="w-full text-xs min-w-[640px]" data-testid="wf-control-table">
        <thead className="text-slate-500 text-left"><tr><th className="py-1.5">组别</th><th>成交笔数</th><th>胜率</th><th>平均净收益</th><th>中位净收益</th><th>盈亏比</th><th>最大回撤</th><th>累计净收益</th></tr></thead>
        <tbody>{rows.map(([n, s]) => (
          <tr key={n} className="border-t border-[#1E2838]"><td className="py-1.5 text-slate-300">{n}</td><td className="font-num">{s?.trades != null ? Math.round(s.trades) : "—"}</td>
            <td className="font-num">{pct(s?.win_rate, 1)}</td><td className="font-num">{pct(s?.mean_net_return, 2)}</td><td className="font-num">{pct(s?.median_net_return, 2)}</td>
            <td className="font-num">{s?.profit_loss_ratio ?? "—"}</td><td className="font-num">{pct(s?.max_drawdown, 1)}</td><td className="font-num">{pct(s?.cum_net_return, 1)}</td></tr>
        ))}</tbody>
      </table>
    </div>
  );
}

const Breakdown = ({ title, obj }) => (
  <div>
    <div className="eyebrow mb-2">{title}</div>
    <KV rows={Object.entries(obj || {}).map(([k, v]) => [v.label || k, `${v.trades} 笔 · 胜率 ${pct(v.win_rate, 0)} · 均值 ${pct(v.mean_net_return, 2)} · 超额 ${pct(v.excess, 2)}`])} />
  </div>
);

export function WalkForwardReport() {
  const [r, setR] = useState(null);
  const [h, setH] = useState("5");
  useEffect(() => { api.get("/research/report?kind=walkforward").then((x) => setR(x.data)).catch(() => setR({ available: false })); }, []);
  if (!r) return null;
  if (!r.available) return <Section title="滚动回测（Walk-Forward）" testid="wf-report"><p className="text-sm text-slate-400" data-testid="wf-report-pending">滚动回测尚未完成。</p></Section>;
  const p = r.payload, x = p.horizons[h];
  return (
    <Section title={`滚动回测 ${p.test_period.join(" ~ ")}`} testid="wf-report" extra={<span className="text-[11px] text-slate-500">{r.model_version} · {dt(r.created_at)}</span>}>
      <div className="space-y-6">
        <div className="flex flex-wrap items-center gap-3"><HzTabs h={h} setH={setH} prefix="wf" /><StatusBadge status={x.status.status} label={x.status.label} testid={`wf-status-${h}`} /></div>
        <ul data-testid="wf-status-checks">{x.status.checks.map((c) => <Check key={c.name} c={c} />)}</ul>
        <ControlTable x={x} />
        <div className="text-xs text-slate-400 space-y-1">
          <div>相对随机对照的超额平均净收益：<b className="font-num text-slate-200">{pct(x.excess_vs_random.point, 2)}</b>（交易日区块 Bootstrap 95%CI {pct(x.excess_vs_random.ci_low, 2)} ~ {pct(x.excess_vs_random.ci_high, 2)}）</div>
          {x.bootstrap_mean_net_return && <div>系统平均净收益 95%CI：{pct(x.bootstrap_mean_net_return.ci_low, 2)} ~ {pct(x.bootstrap_mean_net_return.ci_high, 2)}；胜率 95%CI：{pct(x.bootstrap_win_rate.ci_low, 1)} ~ {pct(x.bootstrap_win_rate.ci_high, 1)}</div>}
          <div>未成交原因：{Object.entries(x.system.unfilled_reasons || {}).map(([k, v]) => `${k} ${v}`).join(" · ") || "无"}</div>
          <div>随机对照：{x.random.draws} 次抽样，固定种子 {x.random.seed}</div>
        </div>
        <div className="grid md:grid-cols-2 gap-6 text-xs"><Breakdown title="按年份" obj={x.by_year} /><Breakdown title="按市场环境" obj={x.by_regime} /></div>
        <ul className="text-[11px] text-slate-500 space-y-1">{p.assumptions.map((a) => <li key={a}>· {a}</li>)}</ul>
        <TradesTable version={r.model_version} horizon={h} />
      </div>
    </Section>
  );
}

function TradesTable({ version, horizon }) {
  const [strategy, setStrategy] = useState("system");
  const [page, setPage] = useState(0);
  const [d, setD] = useState(null);
  useEffect(() => {
    api.get("/research/trades", { params: { version, horizon, strategy, limit: 20, offset: page * 20 } }).then((x) => setD(x.data)).catch(() => {});
  }, [version, horizon, strategy, page]);
  return (
    <div className="space-y-3" data-testid="wf-trades">
      <div className="flex flex-wrap items-center gap-2 text-xs">
        <span className="eyebrow">逐笔交易明细</span>
        {[["system", "系统策略"], ["rsi", "RSI 对照"]].map(([k, l]) => (
          <button key={k} data-testid={`trades-strategy-${k}`} onClick={() => { setStrategy(k); setPage(0); }}
            className={`px-2.5 py-1 rounded-md border ${strategy === k ? "border-blue-500/60 text-blue-100 bg-blue-500/10" : "border-[#222D3D] text-slate-400"}`}>{l}</button>
        ))}
        <a href={`${API}/research/trades/export?version=${version}&horizon=${horizon}`} data-testid="trades-export-btn"
          className="ml-auto inline-flex items-center gap-1 px-2.5 py-1 rounded-md border border-[#222D3D] text-slate-300 hover:text-white"><Download className="w-3.5 h-3.5" /> 导出 CSV</a>
      </div>
      <div className="overflow-x-auto">
        <table className="w-full text-[11px] min-w-[860px]">
          <thead className="text-slate-500 text-left"><tr><th className="py-1.5">信号日</th><th>股票</th><th>入选原因</th><th>模型</th><th>模型分/同日排名（非概率）</th><th>区间上沿</th><th>成交价 / 未成交原因</th><th>卖出价</th><th>净收益</th></tr></thead>
          <tbody>{(d?.items || []).map((t) => (
            <tr key={t.id} className="border-t border-[#1E2838]">
              <td className="py-1.5 font-num">{t.trade_date}</td><td>{t.stock_name || ""} <span className="font-num text-sky-400">{t.stock_code}</span></td>
              <td className="text-slate-400 max-w-[220px] truncate" title={t.reason}>{t.reason}</td><td className="font-num text-slate-500">{t.fold_model}</td>
              <td className="font-num">{t.prob != null ? t.prob.toFixed(3) : "—"} / {t.rank_pct != null ? pct(t.rank_pct, 0) : "—"}</td><td className="font-num">{t.zone_high?.toFixed(2)}</td>
              <td className={t.filled ? "font-num" : "text-amber-300"}>{t.filled ? `${t.entry_price?.toFixed(2)} × ${t.shares}` : t.unfilled_reason}</td>
              <td className="font-num">{t.exit_price?.toFixed(2) ?? "—"}</td><td className={`font-num ${t.net_return > 0 ? "up" : t.net_return < 0 ? "down" : ""}`}>{t.net_return != null ? pct(t.net_return, 2) : "—"}</td>
            </tr>
          ))}</tbody>
        </table>
      </div>
      <div className="flex items-center gap-3 text-xs text-slate-400">
        <button disabled={page === 0} onClick={() => setPage(page - 1)} data-testid="trades-prev" className="disabled:opacity-30">上一页</button>
        <span className="font-num">{page + 1} / {Math.max(1, Math.ceil((d?.total || 0) / 20))} · 共 {d?.total ?? 0} 条</span>
        <button disabled={(page + 1) * 20 >= (d?.total || 0)} onClick={() => setPage(page + 1)} data-testid="trades-next" className="disabled:opacity-30">下一页</button>
      </div>
    </div>
  );
}
