import { useEffect, useState } from "react";
import { toast } from "sonner";
import { Layers, RotateCcw } from "lucide-react";
import { api, errMsg } from "@/lib/api";
import { dt } from "@/lib/format";
import { Section } from "@/components/common";
import { ScoreItems } from "@/components/StrategyStatus";

const GRADE_CLS = {
  A: "border-red-500/50 bg-red-500/10 text-red-200",
  B: "border-amber-500/50 bg-amber-500/10 text-amber-200",
  C: "border-slate-500/40 bg-slate-500/10 text-slate-300",
};

export const GradeBadge = ({ grade, label, testid }) => (
  <span data-testid={testid} className={`inline-flex items-center px-2 py-0.5 rounded-full border text-[11px] font-medium ${GRADE_CLS[grade] || GRADE_CLS.C}`}>
    {grade} 级{label ? ` · ${label}` : ""}
  </span>
);

const grp = (g) => (g && g.trades ? `${g.trades} 笔，胜率 ${(g.win_rate * 100).toFixed(0)}%，每笔 ${(g.mean_net * 100).toFixed(2)}%${g.trades < 20 ? "（样本不足 20 笔，不能据此判断）" : ""}` : "无样本");
const OLD = { v1: "第一版", v2: "第二版" };

function ConsensusBox({ c, hz }) {
  if (!c) return null;
  const d = c.all_minus_rest;
  return (
    <div className="rounded-md bg-[#0F1520] border border-[#1E2838] p-2 text-[11px] text-slate-400 space-y-0.5" data-testid={`v3-consensus-${hz}`}>
      <div className="text-slate-300">多版本一致性（{c.older_models.map((m) => OLD[m] || m).join("、")} 同时打分，受保护测试期实测）</div>
      <div>前几版也都看好：{grp(c.all_agree)}</div>
      {c.partial?.trades > 0 && <div>部分看好：{grp(c.partial)}</div>}
      <div>前几版都不看好：{grp(c.none_agree)}</div>
      {d?.point != null && <div>一致组 − 其余：每笔 {(d.point * 100).toFixed(2)}%（95% 区间 {(d.ci_low * 100).toFixed(2)}%~{(d.ci_high * 100).toFixed(2)}%{d.ci_low > 0 ? "，显著" : "，不显著"}）</div>}
      <div className="text-slate-500">多版本平均排名直接选股：{c.avg_rank_adopted ? "更好，已采用" : `每期 ${(c.avg_rank_diff.point * 100).toFixed(2)}%，不如 3.0 单独选股，未采用`}；一致性只作参考标签</div>
    </div>
  );
}

function HorizonCard({ hz, r, labels }) {
  return (
    <div className="rounded-lg border border-[#222D3D] p-4 space-y-2" data-testid={`v3-horizon-${hz}`}>
      <div className="flex items-center justify-between gap-2">
        <span className="text-sm text-slate-100 font-medium">{hz} 日周期</span>
        <GradeBadge grade={r.grade} label={labels[r.grade]} testid={`v3-grade-${hz}`} />
      </div>
      <p className="text-xs text-slate-300">{r.summary}</p>
      <p className="text-[11px] text-slate-500">可信度：<span className="text-slate-300">{r.credibility}</span> · 门槛：预期扣费后净收益 {r.tau == null ? "> 0（选满前 " : `> ${(r.tau * 100).toFixed(2)}%（最多 `}{r.K} 只）</p>
      <p className="text-[11px] text-slate-300" data-testid={`v3-score-${hz}`}>综合证据评分 <b className="font-num text-slate-100">{r.score ?? "—"}</b> 分</p>
      {r.score_items?.length > 0 && <ScoreItems items={r.score_items} testid={`v3-score-items-${hz}`} />}
      <ConsensusBox c={r.consensus} hz={hz} />
      <p className="text-[11px] text-slate-300" data-testid={`v3-passed-${hz}`}>验收通过 {r.passed ?? "—"}/{r.total ?? "—"} 条{r.accuracy ? ` · 胜率 ${(r.accuracy.win_rate * 100).toFixed(0)}%（${r.accuracy.trades} 笔）` : ""}{r.grade === "C" ? " · 候选仅供参考，不推荐采纳" : ""}</p>
      {r.checks?.length > 0 && (
        <details className="text-[11px] text-slate-400" data-testid={`v3-checks-${hz}`}>
          <summary className="cursor-pointer text-slate-300">查看 {r.total} 条验收明细</summary>
          <ul className="mt-1 space-y-0.5">{r.checks.map((c) => <li key={c.name} className={c.pass ? "text-slate-300" : "text-slate-500"}>{c.pass ? "✓" : "✗"} {c.name}</li>)}</ul>
        </details>
      )}
      <ul className="text-[11px] text-slate-400 space-y-1 list-disc pl-4">{r.evidence.map((e) => <li key={e}>{e}</li>)}</ul>
      <ul className="text-[11px] text-amber-200/80 space-y-1 list-disc pl-4" data-testid={`v3-risks-${hz}`}>{r.risks.map((e) => <li key={e}>风险：{e}</li>)}</ul>
    </div>
  );
}

export default function ModelV3Panel() {
  const [reg, setReg] = useState(null);
  const [vers, setVers] = useState([]);
  const load = () => {
    api.get("/models/v3/registry").then((r) => setReg(r.data)).catch(() => {});
    api.get("/models/versions").then((r) => setVers(r.data.versions || [])).catch(() => {});
  };
  useEffect(load, []);
  const activate = (v) => api.post(`/models/activate/${v}`).then(() => { toast.success(`已切换到 ${v}`); load(); }).catch((e) => toast.error(errMsg(e)));
  if (!reg) return null;
  return (
    <Section title="A-SHARE 3.0 分周期模型配置" testid="v3-panel" extra={<Layers className="w-4 h-4 text-red-300" />}>
      <p className="text-xs text-slate-400 mb-4">每个周期独立评估，等级按综合证据评分自动计算：验收条数、相对旧算法的研究期与受保护期增量、是否好于前几版模型都计分，扣费后亏损扣分（A 正式采用、B 有条件采用、C 暂不采用——C 级仍列出候选，但标注准确率且不推荐采纳）。所有数字为历史实测，不代表未来收益。</p>
      <div className="grid md:grid-cols-3 gap-4">
        {Object.entries(reg.registry).map(([hz, r]) => <HorizonCard key={hz} hz={hz} r={r} labels={reg.grade_labels} />)}
      </div>
      <div className="mt-4 grid md:grid-cols-2 gap-4 text-[11px]">
        <div className="rounded-lg border border-[#222D3D] p-3" data-testid="v3-auxiliary">
          <div className="text-slate-300 mb-1">辅助信号</div>
          {Object.entries(reg.auxiliary).map(([k, a]) => <p key={k} className="text-slate-400"><GradeBadge grade={a.grade} /> {a.role} · 可信度{a.credibility}：{a.note}</p>)}
        </div>
        <div className="rounded-lg border border-[#222D3D] p-3" data-testid="v3-not-adopted">
          <div className="text-slate-300 mb-1">暂不采用 / 历史对照</div>
          {Object.entries(reg.not_adopted).map(([k, v]) => <p key={k} className="text-slate-400">{k}：{v}</p>)}
        </div>
      </div>
      <div className="mt-5">
        <div className="eyebrow mb-2">版本管理（历史版本全部保留，可一键切换）</div>
        <div className="divide-y divide-[#1A2230] border border-[#222D3D] rounded-lg" data-testid="model-versions">
          {vers.map((v) => (
            <div key={v.version} className="flex items-center justify-between gap-3 px-3 py-2 text-xs" data-testid={`model-version-${v.version}`}>
              <span className="font-num text-slate-200">{v.version}</span>
              <span className="text-slate-500">第{v.schema}代 · 训练至 {v.training_end || "—"} · {dt(v.created_at)}</span>
              {v.is_active ? <span className="text-red-300" data-testid="model-version-active">当前使用</span> : (
                <button data-testid={`activate-${v.version}`} onClick={() => activate(v.version)} className="inline-flex items-center gap-1 text-slate-300 hover:text-white">
                  <RotateCcw className="w-3.5 h-3.5" /> 切换到此版本
                </button>
              )}
            </div>
          ))}
        </div>
      </div>
    </Section>
  );
}
