import { AlertTriangle, Info } from "lucide-react";
import { dt, pct, yuan } from "@/lib/format";
import { QuoteBadge } from "@/components/common";
import { StatusBadge, ModeNotice } from "@/components/StrategyStatus";

const FUNNEL = [["initial_match", "初步符合条件"], ["stabilization", "企稳信号不足排除"], ["liquidity", "流动性不足排除"], ["risk", "风险或波动过高排除"],
  ["model", "模型/综合评分不足排除"], ["other", "其他条件排除"], ["final", "最终进入名单"]];

function Funnel({ f }) {
  if (!f) return null;
  return (
    <div className="space-y-1.5">
      <div className="grid grid-cols-2 sm:grid-cols-4 lg:grid-cols-7 gap-2" data-testid="scan-funnel">
        {FUNNEL.filter(([k]) => f[k] != null).map(([k, label]) => (
          <div key={k} className="rounded-lg bg-[#0F1520] border border-[#1E2838] px-3 py-2">
            <div className="text-[11px] text-slate-500">{label}</div>
            <div className="font-num text-lg text-slate-100" data-testid={`funnel-${k}`}>{f[k]}</div>
          </div>
        ))}
      </div>
      <p className="text-[11px] text-slate-500">按顺序逐级筛选：每一级只统计上一级剩下的股票（已分析 {f.analyzed} 只）。</p>
    </div>
  );
}

function AllocationSummary({ a }) {
  if (!a) return null;
  return (
    <div className="text-xs text-slate-300 bg-red-500/5 border border-red-500/20 rounded-lg p-3" data-testid="allocation-summary">
      {a.plan_label}：<b className="font-num">{yuan(a.plan_amount)}</b> · 合计建议占用 <b className="font-num">{yuan(a.total_suggested)}</b> · 剩余现金 <b className="font-num">{yuan(a.remaining_cash)}</b>
      <div className="text-[11px] text-slate-500 mt-1">规则：单只风险预算 {pct(a.rules?.risk_pct, 0)}、单只上限 {pct(a.rules?.max_single_pct, 0)}、近 60 日走势相关性 &gt; {a.rules?.corr_threshold} 合并计算（默认值）。可考虑，不必须买入。</div>
    </div>
  );
}

export default function ScanSummary({ results }) {
  const s = results.summary || {};
  const q = s.quote_meta || {};
  const st = s.strategy_status;
  return (
    <div className="panel p-5 md:p-6 space-y-4 rise" data-testid="scan-summary">
      <div className="flex flex-wrap items-center gap-2 text-xs text-slate-400">
        {st && <StatusBadge status={st.status} label={st.label} testid="summary-strategy-status" />}
        <QuoteBadge type={q.quote_type} label={q.quote_type_label} testid="summary-quote-type" />
        <span>行情时间 <b className="font-num text-slate-200" data-testid="summary-quote-time">{dt(q.quote_time)}</b></span>
        <span>来源 <b className="text-slate-200" data-testid="summary-source">{q.source_label}</b></span>
        {s.model && <span>模型 <b className="font-num text-slate-200">{s.model.version}</b></span>}
        <span>关注周期 <b className="text-slate-200">{s.horizon} 日</b></span>
      </div>
      {st && <ModeNotice status={st.status} s={st} />}
      {s.warnings?.map((w) => (
        <div key={w} className="flex gap-2 text-xs text-amber-200 bg-amber-500/10 border border-amber-500/25 rounded-lg p-3" data-testid="scan-warning">
          <AlertTriangle className="w-4 h-4 shrink-0" /> {w}
        </div>
      ))}
      <AllocationSummary a={s.allocation_summary} />
      {s.no_opportunity_message && (
        <div className="rounded-xl border border-slate-600/40 bg-[#0F1520] p-5" data-testid="empty-candidates-alert">
          <div className="text-lg font-semibold text-slate-100">{s.no_opportunity_message}</div>
          <p className="text-xs text-slate-400 mt-2">系统不会为了凑数放宽条件。以下数字来自本次真实筛选：</p>
        </div>
      )}
      <Funnel f={s.funnel} />
      {s.no_opportunity_message && Object.keys(s.rejection_reasons || {}).length > 0 && (
        <div className="flex flex-wrap gap-2">
          {Object.entries(s.rejection_reasons).slice(0, 8).map(([k, v]) => (
            <span key={k} className="text-[11px] px-2 py-1 rounded bg-slate-800 text-slate-300">{k} <b className="font-num">{v}</b></span>
          ))}
        </div>
      )}
      <div className="flex items-start gap-2 text-[11px] text-slate-500">
        <Info className="w-3.5 h-3.5 shrink-0 mt-0.5" />
        <span>市场上涨比例 {pct(s.market?.up_ratio, 0)}，历史不足 {s.history_insufficient} 只，数据质量不达标 {s.data_quality_failed} 只。{q.note}</span>
      </div>
    </div>
  );
}
