import { createContext, useCallback, useContext, useEffect, useRef, useState } from "react";
import { api, errMsg } from "@/lib/api";

const ScanCtx = createContext(null);
const DONE = ["COMPLETED", "FAILED"];

export function ScanProvider({ children }) {
  const [scanId, setScanId] = useState(() => Number(localStorage.getItem("ashare_last_scan")) || null);
  const [session, setSession] = useState(null);
  const [results, setResults] = useState(null);
  const [error, setError] = useState(null);
  const timer = useRef(null);

  const loadResults = useCallback(async (id) => {
    try {
      const { data } = await api.get(`/scan/${id}/results`);
      setResults(data);
    } catch (e) {
      setError(errMsg(e));
    }
  }, []);

  const poll = useCallback(async (id) => {
    try {
      const { data } = await api.get(`/scan/${id}`);
      setSession(data);
      setError(null);
      if (DONE.includes(data.status)) {
        if (data.status === "COMPLETED") loadResults(id);
        return;
      }
      timer.current = setTimeout(() => poll(id), 1500);
    } catch (e) {
      if (e?.response?.status === 404) {
        localStorage.removeItem("ashare_last_scan");
        setScanId(null);
      } else {
        setError(errMsg(e));
        timer.current = setTimeout(() => poll(id), 4000);
      }
    }
  }, [loadResults]);

  useEffect(() => {
    clearTimeout(timer.current);
    if (scanId) poll(scanId);
    return () => clearTimeout(timer.current);
  }, [scanId, poll]);

  const start = useCallback(async (payload) => {
    setError(null);
    setResults(null);
    const { data } = await api.post("/scan/start", payload);
    localStorage.setItem("ashare_last_scan", data.session_id);
    setSession({ id: data.session_id, status: "INITIALIZING", progress: 0 });
    setScanId(data.session_id);
    return data.session_id;
  }, []);

  const running = session && !DONE.includes(session.status);
  return (
    <ScanCtx.Provider value={{ scanId, session, results, error, start, running }}>
      {children}
    </ScanCtx.Provider>
  );
}

export const useScan = () => useContext(ScanCtx);
