import TomorrowCard from "@/components/TomorrowCard";
import ScanSummary from "@/components/ScanSummary";
import { ResultsGate, PageTitle, Footer } from "@/components/ResultsShared";

export default function TomorrowPage() {
  return (
    <div className="space-y-6" data-testid="tomorrow-page">
      <PageTitle title="明日买入预测" sub="基于今日最新有效价格与历史数据，用分位数回归预测下一个实际交易日（自动跳过周末与节假日）的价格区间。区间是模型估计，不保证成交。" />
      <ResultsGate>
        {(r) => (
          <>
            <ScanSummary results={r} />
            {r.candidates.length > 0 && (
              <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-5" data-testid="tomorrow-candidates">
                {r.candidates.map((c, i) => <TomorrowCard key={c.stock_code} item={c} idx={i} />)}
              </div>
            )}
          </>
        )}
      </ResultsGate>
      <Footer />
    </div>
  );
}
