import { useEffect, useState } from "react";
import { api } from "@/lib/api";
import { pctRaw, tclass, money, dt, REGIME_STYLE, price } from "@/lib/format";
import { QuoteBadge } from "@/components/common";

export default function MarketStatusCard() {
  const [d, setD] = useState(null);
  useEffect(() => { api.get("/market/status").then((r) => setD(r.data)).catch(() => {}); }, []);
  if (!d) return <div className="panel p-6 h-48 animate-pulse" data-testid="market-status-loading" />;
  const ls = d.last_scan;
  const m = ls?.market;
  return (
    <div className="panel p-5 md:p-6 rise" data-testid="market-status-card">
      <div className="flex items-start justify-between gap-4">
        <div>
          <div className="eyebrow">市场状态</div>
          <div className="mt-2 flex items-baseline gap-3">
            <span data-testid="market-phase-label" className="text-2xl font-bold text-slate-100">{d.phase.label}</span>
            {m && <span data-testid="market-regime" className={`text-sm ${REGIME_STYLE[m.regime]}`}>市场环境 · {m.regime_label}</span>}
          </div>
          <div className="text-xs text-slate-500 mt-1">
            {d.phase.date} · {d.phase.is_trading_day ? "交易日" : "非交易日"} · 下一交易日 <span className="font-num">{d.phase.next_trading_day || "—"}</span>
          </div>
        </div>
      </div>
      {m ? (
        <>
          <div className="grid grid-cols-2 sm:grid-cols-3 gap-3 mt-5">
            {m.indices.slice(0, 3).map((i) => (
              <div key={i.code} className="rounded-lg bg-[#0F1520] border border-[#1E2838] p-3" data-testid={`index-${i.code}`}>
                <div className="text-[11px] text-slate-500">{i.name}</div>
                <div className={`font-num text-base mt-0.5 ${tclass(i.change_pct)}`}>{price(i.price)}</div>
                <div className={`font-num text-xs ${tclass(i.change_pct)}`}>{pctRaw(i.change_pct)}</div>
              </div>
            ))}
          </div>
          <div className="flex flex-wrap gap-x-5 gap-y-1 mt-4 text-xs text-slate-400">
            <span>上涨 <b className="font-num up">{m.up_count}</b></span>
            <span>下跌 <b className="font-num down">{m.down_count}</b></span>
            <span>平盘 <b className="font-num">{m.flat_count}</b></span>
            <span>成交额 <b className="font-num text-slate-200">{money(m.total_amount)}</b></span>
          </div>
          <div className="mt-4 pt-4 border-t border-[#1E2838] flex flex-wrap items-center gap-2 text-[11px] text-slate-500" data-testid="last-quote-info">
            最近一次行情 <span className="font-num text-slate-300">{dt(ls.quote_time)}</span>
            <QuoteBadge type={ls.quote_type} label={ls.data?.quote_type_label} />
            <span>{ls.data_source}</span>
          </div>
        </>
      ) : (
        <p className="text-sm text-slate-400 mt-5" data-testid="market-no-scan">尚未进行过分析。行情只在你点击“开始分析”时获取。</p>
      )}
    </div>
  );
}
