import { Link } from "react-router-dom";
import { ArrowUpRight, ShieldAlert } from "lucide-react";
import { price, pctRaw, tclass, pct, yuan, score } from "@/lib/format";
import { StatusPill, DataStamp } from "@/components/common";

export const consensusText = (c) => (c.agree === c.of ? `多版本一致（${c.names.join("、")}也看好）` : c.agree ? `部分一致（${c.names.join("、")}看好）` : "前几版未看好");

function ConsensusTag({ c }) {
  const cls = c.agree === c.of ? "border-red-500/40 text-red-200" : c.agree ? "border-slate-500/40 text-slate-300" : "border-slate-600/40 text-slate-500";
  return <span className={`inline-block whitespace-nowrap ml-1 px-1.5 py-0.5 rounded border text-[11px] ${cls}`} data-testid="consensus-tag">{consensusText(c)}</span>;
}

export function ProbLine({ item }) {
  const m = item.model || {};
  const h = item.horizon;
  if (!m.available) return <span className="text-xs text-slate-500">模型未就绪</span>;
  if (m[`exp_net_${h}d`] != null) return (
    <span className="text-xs text-slate-300" data-testid="prob-line">
      预期{h}日扣费后净收益 <b className="font-num text-red-300">{pct(m[`exp_net_${h}d`], 2)}</b> · 正收益概率 <b className="font-num">{pct(m[`prob_${h}d`], 0)}</b>
      {m[`grade_${h}d`] === "C" && <span className="ml-1 px-1.5 py-0.5 rounded border border-amber-500/40 text-amber-200 text-[11px]" data-testid="not-recommended-tag">不推荐采纳{m[`accuracy_${h}d`] ? ` · 验收期胜率 ${pct(m[`accuracy_${h}d`].win_rate, 0)}` : ""}</span>}
      {m[`consensus_${h}d`] && <ConsensusTag c={m[`consensus_${h}d`]} />}
      <span className="ml-1 text-slate-500" data-testid="grade-line">（{m[`grade_${h}d`]} 级，可信度{m[`credibility_${h}d`]}{m.pair_rank_5d != null && h === 5 ? `；5日同行业配对辅助排名前 ${pct(Math.max(0.01, 1 - m.pair_rank_5d), 0)}` : ""}）</span>
    </span>
  );
  return m[`calibrated_${h}d`] && m[`prob_${h}d`] != null ? (
    <span className="text-xs text-slate-300" data-testid="prob-line">未来{h}日正收益概率 <b className="font-num text-red-300">{pct(m[`prob_${h}d`], 0)}</b></span>
  ) : (
    <span className="text-xs text-slate-300" data-testid="prob-line">模型评分 <b className="font-num text-slate-100">{score(m.model_score)}</b><span className="text-slate-500">（概率校准未通过，非概率）</span></span>
  );
}

function Head({ item }) {
  return (
    <div className="flex items-start justify-between gap-3">
      <div className="min-w-0">
        <div className="flex items-center gap-2">
          {item.candidate_rank && <span className="font-num text-xs w-6 h-6 rounded-md bg-red-500/15 text-red-300 grid place-items-center">{item.candidate_rank}</span>}
          <span className="text-lg font-semibold text-slate-100 truncate">{item.stock_name}</span>
        </div>
        <div className="text-xs text-slate-500 mt-0.5">
          <span className="font-num text-sky-400 tracking-wider">{item.stock_code}</span> · {item.exchange_label} · {item.board_label}
        </div>
      </div>
      <div className="text-right shrink-0">
        <div className={`font-num text-xl font-bold ${tclass(item.change_pct)}`}>{price(item.price)}</div>
        <div className={`font-num text-xs ${tclass(item.change_pct)}`}>{pctRaw(item.change_pct)}</div>
      </div>
    </div>
  );
}

export default function CandidateCard({ item, idx = 0 }) {
  const t = item.today || {};
  const formal = ["FORMAL", "CONDITIONAL"].includes(item.strategy_status?.status) || !item.strategy_status;
  return (
    <article data-testid={`candidate-card-${item.stock_code}`} style={{ animationDelay: `${idx * 70}ms` }}
      className="panel p-5 rise hover:border-blue-500/40 transition-colors flex flex-col gap-4">
      <Head item={item} />
      <div className="rounded-lg bg-[#0F1520] border border-[#1E2838] p-4">
        <div className="flex items-center justify-between gap-2">
          <span className="eyebrow">{formal ? "今日参考买入区间" : "观察参考区间"}</span>
          <StatusPill status={t.status} label={t.status_label} testid={`today-status-${item.stock_code}`} />
        </div>
        <div className="font-num text-2xl text-slate-100 mt-2" data-testid={`today-zone-${item.stock_code}`}>
          {price(t.today_buy_zone_low)} <span className="text-slate-600">–</span> {price(t.today_buy_zone_high)}
        </div>
        <div className="text-[11px] text-slate-500 mt-1">参考价 <span className="font-num text-slate-300">{price(t.today_reference_price)}</span> · 涨停 {price(item.limit_up)} / 跌停 {price(item.limit_down)}</div>
      </div>
      <div className="flex flex-col gap-2">
        <div><span className="eyebrow whitespace-nowrap">综合评分</span> <span className="font-num text-2xl text-slate-100 ml-2" data-testid={`overall-score-${item.stock_code}`}>{score(item.overall_candidate_score)}</span></div>
        <ProbLine item={item} />
      </div>
      <ul className="space-y-1.5 text-xs text-slate-300">
        {(t.today_entry_conditions || []).slice(0, 3).map((c) => <li key={c} className="flex gap-2"><span className="text-blue-400">›</span>{c}</li>)}
      </ul>
      <MoneyLine item={item} formal={formal} />
      {(item.plan_alerts || []).length > 0 && (
        <div className="text-[11px] text-amber-200 bg-amber-500/10 border border-amber-500/25 rounded-lg px-3 py-2" data-testid={`plan-alert-${item.stock_code}`}>
          暂不建议按原计划买入：{item.plan_alerts.join("；")}
        </div>
      )}
      <div className="flex items-start gap-2 text-[11px] text-amber-200/80">
        <ShieldAlert className="w-3.5 h-3.5 shrink-0 mt-0.5" /> <span>{(item.risks || []).slice(0, 2).join("；")}</span>
      </div>
      <div className="mt-auto flex items-center justify-between gap-2">
        <DataStamp item={item} />
        <Link to={`/stock/${item.stock_code}`} data-testid={`candidate-detail-link-${item.stock_code}`} className="text-xs text-blue-300 hover:text-blue-200 flex items-center gap-1 shrink-0">
          详情 <ArrowUpRight className="w-3.5 h-3.5" />
        </Link>
      </div>
    </article>
  );
}

export function MoneyLine({ item, formal }) {
  const a = item.allocation;
  const l = item.lot_info;
  if (formal && a && !(a.shares > 0)) {
    return <div className="text-[11px] text-slate-400 bg-[#0F1520] rounded-lg px-3 py-2" data-testid={`allocation-${item.stock_code}`}>不足一手，本只不分配资金{a.why?.length ? `（${a.why[a.why.length - 1]}）` : ""}</div>;
  }
  if (formal && a) {
    return (
      <div className="text-[11px] text-slate-300 bg-[#0F1520] rounded-lg px-3 py-2" data-testid={`allocation-${item.stock_code}`}>
        可考虑投入 <b className="font-num text-slate-100">{yuan(a.suggested_amount)}</b>（{a.shares} 股，费用约 {yuan(a.estimated_cost)}）
        <span className="text-slate-500"> · {a.plan_label}</span>
      </div>
    );
  }
  if (!l) return null;
  return (
    <div className="text-[11px] text-slate-400 bg-[#0F1520] rounded-lg px-3 py-2" data-testid={`lot-info-${item.stock_code}`}>
      一手（{l.min_lot} 股）约需 <b className="font-num text-slate-200">{yuan(l.one_lot_cost)}</b>
      {l.max_quantity_in_plan != null && <> · 计划金额内最多 <b className="font-num text-slate-200">{l.max_quantity_in_plan}</b> 股</>}
    </div>
  );
}

export { Head as CardHead };
