import { useEffect, useState } from "react";
import { ShieldCheck, Eye, PauseCircle, Loader2 } from "lucide-react";
import { api } from "@/lib/api";

export const STATUS_STYLE = {
  FORMAL: { cls: "border-red-500/40 bg-red-500/10 text-red-200", Icon: ShieldCheck },
  OBSERVATION: { cls: "border-slate-500/40 bg-slate-500/10 text-slate-200", Icon: Eye },
  CONDITIONAL: { cls: "border-amber-500/40 bg-amber-500/10 text-amber-200", Icon: ShieldCheck },
  PAUSED: { cls: "border-amber-500/40 bg-amber-500/10 text-amber-200", Icon: PauseCircle },
};

export const StatusBadge = ({ status, label, testid }) => {
  const s = STATUS_STYLE[status] || STATUS_STYLE.OBSERVATION;
  return (
    <span data-testid={testid} className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full border text-xs font-medium ${s.cls}`}>
      <s.Icon className="w-3.5 h-3.5" /> {label}
    </span>
  );
};

export const accText = (a) => a ? `验收期（${a.period?.[0]}~${a.period?.[1]}）实测：胜率 ${(a.win_rate * 100).toFixed(0)}%（${a.trades} 笔），平均每笔扣费后 ${(a.mean_trade_net_return * 100).toFixed(2)}%，盈亏比 ${a.profit_loss_ratio}` : "暂无验收期实测准确率";

export const ScoreItems = ({ items, testid }) => (
  <ul className="text-[11px] text-slate-400 space-y-0.5" data-testid={testid}>
    {items.map((i) => (
      <li key={i.name}>
        <span className={`font-num mr-1 ${i.points > 0 ? "text-red-300" : i.points < 0 ? "text-green-300" : "text-slate-500"}`}>{i.points > 0 ? "+" : ""}{i.points}</span>{i.name}
      </li>
    ))}
  </ul>
);

export const ModeNotice = ({ status, s }) => {
  if (status === "FORMAL") return null;
  if (s?.grade === "C") return (
    <p data-testid="mode-notice" className="text-xs text-amber-200/90 leading-relaxed">
      C 级 · 暂不采用：该周期{s.score != null ? `综合证据评分 ${s.score} 分` : `验收通过 ${s.passed ?? "—"}/${s.total ?? "—"} 条`}（规则：{s.rule?.replace("综合证据评分 ", "")}）。以下候选仅供参考，<b>不推荐采纳</b>，不提供建议投入金额。{accText(s.accuracy)}。
    </p>
  );
  if (status === "CONDITIONAL") return <p data-testid="mode-notice" className="text-xs text-amber-200/80 leading-relaxed">有条件采用：模型相对旧方案有进步，但证据仍不充分或存在明显风险。候选和建议金额仅供参考，请结合风险提示自行判断。</p>;
  const text = status === "PAUSED"
    ? "策略在独立滚动回测中显著差于随机对照组，已暂停推荐，只保留行情和技术条件观察。"
    : "目前尚未证明系统选股能力优于对照组。以下为市场观察名单，区间为观察参考区间，不提供建议投入金额。";
  return <p data-testid="mode-notice" className="text-xs text-slate-400 leading-relaxed">{text}</p>;
};

export default function StrategyStatusCard({ horizon = 5 }) {
  const [d, setD] = useState(null);
  useEffect(() => {
    let ok = true;
    setD(null);
    api.get(`/strategy/status?horizon=${horizon}`).then((r) => ok && setD(r.data)).catch(() => ok && setD({ status: "OBSERVATION", label: "观察分析模式", reason: "状态读取失败，按保守原则显示" }));
    return () => { ok = false; };
  }, [horizon]);
  if (!d) return <div className="panel p-5"><Loader2 className="w-4 h-4 animate-spin text-slate-500" /></div>;
  const job = d.research_job;
  return (
    <div className="panel p-5 space-y-3 rise" data-testid="strategy-status-card">
      <div className="flex items-center justify-between gap-2">
        <span className="eyebrow">策略验证状态 · {horizon} 日</span>
        <StatusBadge status={d.status} label={d.label} testid="strategy-status-badge" />
      </div>
      <p className="text-xs text-slate-400 leading-relaxed" data-testid="strategy-status-reason">{d.reason}{d.credibility ? `（可信度：${d.credibility}）` : ""}</p>
      {d.grade && <p className="text-[11px] text-slate-300" data-testid="strategy-accuracy">综合证据评分 <b className="font-num">{d.score ?? "—"}</b> 分（规则：{d.rule?.replace("综合证据评分 ", "")}）· 验收 {d.passed ?? "—"}/{d.total ?? "—"} 条 · {accText(d.accuracy)}</p>}
      {d.score_items?.length > 0 && <ScoreItems items={d.score_items} testid="strategy-score-items" />}
      {d.evidence && <ul className="text-[11px] text-slate-400 list-disc pl-4 space-y-0.5" data-testid="strategy-evidence">{d.evidence.map((e) => <li key={e}>{e}</li>)}</ul>}
      {d.risks && <ul className="text-[11px] text-amber-200/80 list-disc pl-4 space-y-0.5" data-testid="strategy-risks">{d.risks.map((e) => <li key={e}>风险：{e}</li>)}</ul>}
      <p className="text-[11px] text-slate-500">{d.grade ? "由 A-SHARE 3.0 分周期三级评估判定（依据研究期与受保护测试期实测），" : "由当前模型版本的独立滚动回测自动判定，"}模型版本 <span className="font-num text-slate-300">{d.model_version || "—"}</span>。</p>
      {job?.status === "RUNNING" && (
        <div className="text-[11px] text-blue-200 bg-blue-500/10 border border-blue-500/20 rounded-md px-3 py-2" data-testid="research-job-running">
          第二版训练与滚动回测正在后台运行（{job.progress ?? 0}%）：{job.message}。期间继续使用当前模型。
        </div>
      )}
    </div>
  );
}
