import { Link } from "react-router-dom";
import { ArrowUpRight } from "lucide-react";
import { price } from "@/lib/format";
import { StatusPill } from "@/components/common";
import { CardHead, ProbLine } from "@/components/CandidateCard";

export default function TomorrowCard({ item, idx = 0 }) {
  const t = item.tomorrow || {};
  return (
    <article data-testid={`tomorrow-card-${item.stock_code}`} style={{ animationDelay: `${idx * 70}ms` }}
      className="panel p-5 rise hover:border-blue-500/40 transition-colors flex flex-col gap-4">
      <CardHead item={item} />
      <div className="text-xs text-slate-500">
        {item.quote_type === "TODAY_CLOSE" || item.quote_type === "PREV_CLOSE" ? "收盘价" : "最新有效价"} <span className="font-num text-slate-300">{price(t.reference_close)}</span>
        {" · "}下一交易日 <span className="font-num text-slate-300" data-testid={`next-day-${item.stock_code}`}>{t.next_trading_day || "—"}</span>
      </div>
      <div className="grid grid-cols-3 gap-2 text-center">
        {[["预测低位", t.tomorrow_predicted_price_low], ["预测中位", t.tomorrow_predicted_price_median], ["预测高位", t.tomorrow_predicted_price_high]].map(([l, v]) => (
          <div key={l} className="rounded-lg bg-[#0F1520] border border-[#1E2838] py-2.5">
            <div className="text-[10px] text-slate-500">{l}</div>
            <div className="font-num text-slate-100">{price(v)}</div>
          </div>
        ))}
      </div>
      <div className="rounded-lg bg-blue-500/5 border border-blue-500/25 p-4">
        <div className="flex items-center justify-between gap-2">
          <span className="eyebrow">明日参考买入区间</span>
          <StatusPill status={t.status} label={t.status_label} testid={`tomorrow-status-${item.stock_code}`} />
        </div>
        <div className="font-num text-2xl text-slate-100 mt-2" data-testid={`tomorrow-zone-${item.stock_code}`}>
          {price(t.tomorrow_buy_zone_low)} <span className="text-slate-600">–</span> {price(t.tomorrow_buy_zone_high)}
        </div>
      </div>
      <ProbLine item={item} />
      <div>
        <div className="eyebrow mb-2">开盘后观察条件</div>
        <ul className="space-y-1.5 text-xs text-slate-300">
          {(t.tomorrow_entry_conditions || []).slice(0, 4).map((c) => <li key={c} className="flex gap-2"><span className="text-blue-400">›</span>{c}</li>)}
        </ul>
      </div>
      <details className="text-[11px] text-slate-500">
        <summary className="cursor-pointer hover:text-slate-300" data-testid={`tomorrow-basis-${item.stock_code}`}>预测数据依据</summary>
        <ul className="mt-2 space-y-1">{(t.basis || []).map((b) => <li key={b}>· {b}</li>)}</ul>
      </details>
      <Link to={`/stock/${item.stock_code}`} data-testid={`tomorrow-detail-link-${item.stock_code}`} className="mt-auto text-xs text-blue-300 hover:text-blue-200 flex items-center gap-1 self-end">
        详情 <ArrowUpRight className="w-3.5 h-3.5" />
      </Link>
    </article>
  );
}
