import { useState } from "react";
import { Link } from "react-router-dom";
import MarketStatusCard from "@/components/MarketStatusCard";
import AnalysisForm from "@/components/AnalysisForm";
import ScanProgress from "@/components/ScanProgress";
import ScanSummary from "@/components/ScanSummary";
import CandidateCard from "@/components/CandidateCard";
import ReadinessBanner from "@/components/ReadinessBanner";
import StrategyStatusCard from "@/components/StrategyStatus";
import { Disclaimer } from "@/components/common";
import { useScan } from "@/hooks/useScan";

const TITLES = { FORMAL: "本次正式候选", CONDITIONAL: "本次有条件候选", OBSERVATION: "市场观察名单", PAUSED: "技术条件观察" };

export default function HomePage() {
  const { session, results } = useScan();
  const [formH, setFormH] = useState(null);
  const st = results?.summary?.strategy_status?.status;
  return (
    <div className="space-y-6" data-testid="home-page">
      <div className="rise">
        <div className="eyebrow">PERSONAL A-SHARE INTELLIGENCE</div>
        <h1 className="text-4xl sm:text-5xl lg:text-6xl font-bold tracking-tight text-slate-50 mt-2">
          你给计划，<span className="text-red-400">系统负责选股</span>
        </h1>
        <p className="text-sm md:text-base text-slate-400 mt-3 max-w-2xl">只需填写资金、价格范围和三个开关。低位、企稳、风险和模型计算都由系统完成；系统能力是否真的优于对照组，以独立滚动回测为准并如实标明。</p>
      </div>
      <ReadinessBanner />
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
        <div className="lg:col-span-7 space-y-6"><AnalysisForm onHorizon={setFormH} sessionHorizon={session?.horizon} /></div>
        <div className="lg:col-span-5 space-y-6"><StrategyStatusCard horizon={formH || session?.horizon || 5} /><MarketStatusCard /></div>
      </div>
      {session && <ScanProgress session={session} />}
      {results && session?.status === "COMPLETED" && (
        <>
          <ScanSummary results={results} />
          {results.candidates.length > 0 && (
            <div>
              <div className="flex items-end justify-between mb-4">
                <h2 className="text-base md:text-lg font-semibold text-slate-100" data-testid="candidates-title">{results.summary.strategy_status?.grade === "C" ? "参考候选 · 不推荐采纳" : TITLES[st] || "本次候选"}（{results.candidates.length} 只）</h2>
                <div className="flex gap-4 text-xs">
                  <Link to="/today" data-testid="goto-today" className="text-blue-300 hover:text-blue-200">今日区间 →</Link>
                  <Link to="/tomorrow" data-testid="goto-tomorrow" className="text-blue-300 hover:text-blue-200">下一交易日 →</Link>
                </div>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-5">
                {results.candidates.map((c, i) => <CandidateCard key={c.stock_code} item={c} idx={i} />)}
              </div>
            </div>
          )}
        </>
      )}
      <Disclaimer />
    </div>
  );
}
