import { ComposedChart, Line, Area, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, ReferenceArea, CartesianGrid, BarChart, Cell } from "recharts";

const tip = { contentStyle: { background: "#0F1520", border: "1px solid #222D3D", borderRadius: 8, fontSize: 12 }, labelStyle: { color: "#94A3B8" } };

export function PriceChart({ bars, today, tomorrow }) {
  const data = bars.map((b) => ({ ...b, d: b.trade_date.slice(5) }));
  const lo = Math.min(...bars.map((b) => b.low), today?.today_buy_zone_low ?? Infinity, tomorrow?.tomorrow_buy_zone_low ?? Infinity);
  const hi = Math.max(...bars.map((b) => b.high));
  return (
    <div className="h-72" data-testid="price-chart">
      <ResponsiveContainer width="100%" height="100%">
        <ComposedChart data={data} margin={{ top: 8, right: 8, left: -10, bottom: 0 }}>
          <CartesianGrid stroke="#1A2332" vertical={false} />
          <XAxis dataKey="d" tick={{ fill: "#64748B", fontSize: 10 }} minTickGap={30} />
          <YAxis domain={[lo * 0.97, hi * 1.02]} tick={{ fill: "#64748B", fontSize: 10 }} tickFormatter={(v) => v.toFixed(2)} width={56} />
          <Tooltip {...tip} formatter={(v) => (typeof v === "number" ? v.toFixed(2) : v)} />
          {today?.today_buy_zone_low && <ReferenceArea y1={today.today_buy_zone_low} y2={today.today_buy_zone_high} fill="#EF4444" fillOpacity={0.12} stroke="#EF4444" strokeOpacity={0.4} />}
          {tomorrow?.tomorrow_buy_zone_low && <ReferenceArea y1={tomorrow.tomorrow_buy_zone_low} y2={tomorrow.tomorrow_buy_zone_high} fill="#3B82F6" fillOpacity={0.1} stroke="#3B82F6" strokeOpacity={0.4} />}
          <Area type="monotone" dataKey="close" name="收盘" stroke="#E2E8F0" strokeWidth={1.6} fill="#3B82F6" fillOpacity={0.06} />
          <Line type="monotone" dataKey="ma5" name="MA5" stroke="#F59E0B" dot={false} strokeWidth={1} />
          <Line type="monotone" dataKey="ma20" name="MA20" stroke="#A78BFA" dot={false} strokeWidth={1} />
          <Line type="monotone" dataKey="ma60" name="MA60" stroke="#22D3EE" dot={false} strokeWidth={1} />
        </ComposedChart>
      </ResponsiveContainer>
    </div>
  );
}

export function VolumeChart({ bars }) {
  const data = bars.map((b, i) => ({ d: b.trade_date.slice(5), v: b.volume / 100, up: i === 0 || b.close >= bars[i - 1].close }));
  return (
    <div className="h-28" data-testid="volume-chart">
      <ResponsiveContainer width="100%" height="100%">
        <BarChart data={data} margin={{ top: 0, right: 8, left: -10, bottom: 0 }}>
          <XAxis dataKey="d" hide />
          <YAxis tick={{ fill: "#64748B", fontSize: 10 }} width={56} tickFormatter={(v) => (v >= 1e4 ? `${(v / 1e4).toFixed(0)}万` : v)} />
          <Tooltip {...tip} formatter={(v) => [`${Math.round(v)} 手`, "成交量"]} />
          <Bar dataKey="v">{data.map((x, i) => <Cell key={i} fill={x.up ? "#EF4444" : "#10B981"} fillOpacity={0.7} />)}</Bar>
        </BarChart>
      </ResponsiveContainer>
    </div>
  );
}

export function CalibrationChart({ bins }) {
  const data = (bins || []).map((b) => ({ x: b.mean_pred, pred: b.mean_pred, actual: b.actual_rate, n: b.count }));
  return (
    <div className="h-52" data-testid="calibration-chart">
      <ResponsiveContainer width="100%" height="100%">
        <ComposedChart data={data} margin={{ top: 8, right: 8, left: -16, bottom: 0 }}>
          <CartesianGrid stroke="#1A2332" />
          <XAxis dataKey="x" type="number" domain={[0, 1]} tick={{ fill: "#64748B", fontSize: 10 }} tickFormatter={(v) => `${Math.round(v * 100)}%`} />
          <YAxis domain={[0, 1]} tick={{ fill: "#64748B", fontSize: 10 }} tickFormatter={(v) => `${Math.round(v * 100)}%`} />
          <Tooltip {...tip} formatter={(v, n) => [`${(v * 100).toFixed(1)}%`, n]} />
          <Line dataKey="pred" name="理想（预测=实际）" stroke="#475569" strokeDasharray="4 4" dot={false} />
          <Line dataKey="actual" name="实际正收益比例" stroke="#EF4444" strokeWidth={2} />
        </ComposedChart>
      </ResponsiveContainer>
    </div>
  );
}
