import { NavLink, Link } from "react-router-dom";
import { useEffect, useState } from "react";
import { Activity, Home, CalendarClock, Sunrise, History, Cpu } from "lucide-react";
import { api } from "@/lib/api";
import { useScan } from "@/hooks/useScan";

const NAV = [
  { to: "/", label: "首页", icon: Home, id: "home" },
  { to: "/today", label: "今日买入", icon: CalendarClock, id: "today" },
  { to: "/tomorrow", label: "明日预测", icon: Sunrise, id: "tomorrow" },
  { to: "/history", label: "历史记录", icon: History, id: "history" },
  { to: "/models", label: "模型与数据", icon: Cpu, id: "models" },
];

function PhaseBadge() {
  const [ph, setPh] = useState(null);
  useEffect(() => {
    const load = () => api.get("/market/status").then((r) => setPh(r.data.phase)).catch(() => {});
    load();
    const t = setInterval(load, 60000);
    return () => clearInterval(t);
  }, []);
  if (!ph) return null;
  return (
    <span data-testid="market-phase-badge" className="hidden sm:inline-flex items-center gap-2 text-xs text-slate-300 px-3 py-1.5 rounded-full border border-[#222D3D] bg-[#0F1520]">
      <span className={`w-2 h-2 rounded-full ${ph.is_open ? "bg-red-400 animate-pulse" : "bg-slate-500"}`} />
      {ph.label} · <span className="font-num">{ph.now.slice(11, 16)}</span>
    </span>
  );
}

export default function Layout({ children }) {
  const { running, session } = useScan();
  return (
    <div className="min-h-screen grain pb-24 md:pb-10">
      <header className="sticky top-0 z-40 border-b border-[#1A2332] bg-[#0B0F17]/85 backdrop-blur-xl">
        <div className="max-w-7xl mx-auto px-4 md:px-8 h-16 flex items-center gap-6">
          <Link to="/" data-testid="brand-link" className="flex items-center gap-2.5 shrink-0">
            <span className="w-8 h-8 rounded-lg bg-gradient-to-br from-red-500 to-red-700 grid place-items-center shadow-lg shadow-red-900/40">
              <Activity className="w-4 h-4 text-white" />
            </span>
            <span className="leading-tight">
              <span className="block text-sm font-bold text-slate-100 tracking-tight">A股智能选股</span>
              <span className="block text-[10px] text-slate-500 tracking-[0.2em]">PERSONAL A-SHARE</span>
            </span>
          </Link>
          <nav className="hidden md:flex items-center gap-1">
            {NAV.map((n) => (
              <NavLink key={n.to} to={n.to} end data-testid={`nav-tab-${n.id}`}
                className={({ isActive }) => `px-3 py-2 rounded-lg text-sm transition-colors ${isActive ? "bg-[#1E293B] text-white" : "text-slate-400 hover:text-slate-100 hover:bg-[#151C28]"}`}>
                {n.label}
              </NavLink>
            ))}
          </nav>
          <div className="ml-auto flex items-center gap-3">
            {running && (
              <Link to="/" data-testid="header-scan-running" className="text-xs px-3 py-1.5 rounded-full bg-blue-500/15 text-blue-300 border border-blue-500/30 scan-shimmer">
                分析中 <span className="font-num">{Math.round(session?.progress || 0)}%</span>
              </Link>
            )}
            <PhaseBadge />
          </div>
        </div>
      </header>
      <main className="max-w-7xl mx-auto px-4 md:px-8 py-6 md:py-10">{children}</main>
      <nav className="md:hidden fixed bottom-0 inset-x-0 z-40 bg-[#0B0F17]/95 backdrop-blur-xl border-t border-[#1A2332] grid grid-cols-5">
        {NAV.map((n) => (
          <NavLink key={n.to} to={n.to} end data-testid={`mobile-nav-${n.id}`}
            className={({ isActive }) => `flex flex-col items-center gap-1 py-2.5 text-[10px] ${isActive ? "text-red-300" : "text-slate-500"}`}>
            <n.icon className="w-5 h-5" />
            {n.label}
          </NavLink>
        ))}
      </nav>
    </div>
  );
}
