import CandidateCard from "@/components/CandidateCard";
import ScanSummary from "@/components/ScanSummary";
import { ResultsGate, Watchlist, PageTitle, Footer } from "@/components/ResultsShared";

export default function TodayPage() {
  return (
    <div className="space-y-6" data-testid="today-page">
      <PageTitle title="今日买入分析" sub="根据最新可用行情计算的参考买入区间。进入区间不代表自动买入，请结合触发条件判断。" />
      <ResultsGate>
        {(r) => (
          <>
            <ScanSummary results={r} />
            {r.candidates.length > 0 && (
              <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-5" data-testid="today-candidates">
                {r.candidates.map((c, i) => <CandidateCard key={c.stock_code} item={c} idx={i} />)}
              </div>
            )}
            <Watchlist items={r.watchlist} />
          </>
        )}
      </ResultsGate>
      <Footer />
    </div>
  );
}
