import { Link } from "react-router-dom";
import { useScan } from "@/hooks/useScan";
import { Empty, Disclaimer } from "@/components/common";
import ScanSummary from "@/components/ScanSummary";
import { price, score, pctRaw, tclass } from "@/lib/format";

export function ResultsGate({ children }) {
  const { session, results, running } = useScan();
  if (!session) return <Empty title="还没有分析结果" testid="no-scan-empty">请先在<Link to="/" className="text-blue-300">首页</Link>输入资金和要求并点击“开始分析”。</Empty>;
  if (running) return <Empty title="分析进行中…" testid="scan-running-empty">进度 {Math.round(session.progress || 0)}%，完成后自动显示。<Link to="/" className="text-blue-300 ml-1">查看进度</Link></Empty>;
  if (session.status === "FAILED") return <Empty title="本次分析失败" testid="scan-failed-empty">{session.error}</Empty>;
  if (!results) return <div className="panel h-40 animate-pulse" />;
  return children(results);
}

export function Watchlist({ items }) {
  if (!items?.length) return null;
  return (
    <details className="panel p-5" data-testid="watchlist">
      <summary className="cursor-pointer text-sm text-slate-300">评分靠前但未通过门槛的股票（{items.length}，仅供观察，不是推荐）</summary>
      <div className="overflow-x-auto mt-4">
        <table className="w-full text-xs">
          <thead className="text-slate-500"><tr className="text-left">
            <th className="py-2 pr-3">股票</th><th className="pr-3">现价</th><th className="pr-3">综合</th><th className="pr-3">低位</th><th className="pr-3">企稳</th><th className="pr-3">风险</th><th>未通过原因</th>
          </tr></thead>
          <tbody>
            {items.map((w) => (
              <tr key={w.stock_code} className="border-t border-[#1E2838]" data-testid={`watch-row-${w.stock_code}`}>
                <td className="py-2 pr-3"><Link to={`/stock/${w.stock_code}`} className="text-slate-200 hover:text-blue-300">{w.stock_name} <span className="font-num text-sky-400">{w.stock_code}</span></Link></td>
                <td className={`pr-3 font-num ${tclass(w.change_pct)}`}>{price(w.price)} {pctRaw(w.change_pct)}</td>
                <td className="pr-3 font-num">{score(w.overall_candidate_score)}</td>
                <td className="pr-3 font-num">{score(w.scores.low_position_score)}</td>
                <td className="pr-3 font-num">{score(w.scores.stabilization_score)}</td>
                <td className="pr-3 font-num">{score(w.scores.risk_score)}</td>
                <td className="text-slate-400">{w.rejections.join("、")}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </details>
  );
}

export function PageTitle({ title, sub }) {
  return (
    <div className="rise">
      <h1 className="text-3xl sm:text-4xl font-bold tracking-tight text-slate-50">{title}</h1>
      {sub && <p className="text-sm text-slate-400 mt-2 max-w-2xl">{sub}</p>}
    </div>
  );
}

export const Footer = () => <Disclaimer />;
