import { Check, Loader2, X, Circle } from "lucide-react";
import { dt } from "@/lib/format";

const ALL = [
  ["INITIALIZING", "初始化"], ["FETCHING_MARKET_DATA", "获取行情"], ["VALIDATING_DATA", "校验数据"],
  ["LOADING_HISTORY", "加载历史"], ["CALCULATING_FEATURES", "计算特征"], ["RUNNING_MODELS", "运行模型"],
  ["CALCULATING_BUY_ZONES", "计算买入区间"], ["GENERATING_RESULTS", "生成结果"],
];

function StepIcon({ st }) {
  if (st === "DONE") return <Check className="w-3.5 h-3.5 text-red-300" />;
  if (st === "RUNNING") return <Loader2 className="w-3.5 h-3.5 text-blue-300 animate-spin" />;
  if (st === "FAILED") return <X className="w-3.5 h-3.5 text-amber-300" />;
  return <Circle className="w-3 h-3 text-slate-600" />;
}

export default function ScanProgress({ session }) {
  const stages = session?.stage_detail?.stages || [];
  const byName = Object.fromEntries(stages.map((s) => [s.name, s.status]));
  const failed = session.status === "FAILED";
  const done = session.status === "COMPLETED";
  const pct = done ? 100 : Math.round(session.progress || 0);
  const msgs = session?.stage_detail?.messages || [];
  return (
    <div className="panel p-5 md:p-6 rise" data-testid="scan-progress-stepper">
      <div className="flex items-center justify-between">
        <div>
          <div className="eyebrow">分析 #{session.id}</div>
          <div className="text-lg font-semibold text-slate-100 mt-1" data-testid="scan-status-text">
            {failed ? "分析失败" : done ? "分析完成" : "正在扫描全市场…"}
          </div>
        </div>
        <div className="font-num text-3xl text-slate-100" data-testid="scan-progress-percent">{pct}<span className="text-base text-slate-500">%</span></div>
      </div>
      <div className={`h-1.5 rounded-full bg-slate-800 mt-4 overflow-hidden ${!done && !failed ? "scan-shimmer" : ""}`}>
        <div className={`h-full transition-[width] duration-700 ${failed ? "bg-amber-500" : "bg-gradient-to-r from-blue-500 to-red-500"}`} style={{ width: `${pct}%` }} />
      </div>
      <ol className="grid grid-cols-2 sm:grid-cols-4 gap-2 mt-5">
        {ALL.map(([k, label], i) => {
          const st = byName[k] || (done ? "DONE" : "PENDING");
          return (
            <li key={k} data-testid={`scan-stage-${k}`} className={`flex items-center gap-2 text-xs px-2.5 py-2 rounded-lg border ${st === "RUNNING" ? "border-blue-500/40 bg-blue-500/5 text-slate-100" : "border-[#1E2838] text-slate-400"}`}>
              <StepIcon st={st} /> <span className="font-num text-slate-600">{i + 1}</span> {label}
            </li>
          );
        })}
      </ol>
      {(session.universe_size || done) && (
        <div className="grid grid-cols-3 sm:grid-cols-6 gap-3 mt-5 text-center" data-testid="scan-coverage-counts">
          {[["股票池", session.universe_size], ["获取行情", session.success_count], ["被过滤", session.filtered_count],
            ["获取失败", session.failed_count], ["数据异常", session.anomaly_count], ["实际分析", session.analyzed_count]].map(([l, v]) => (
            <div key={l} className="rounded-lg bg-[#0F1520] py-2">
              <div className="font-num text-slate-100">{v ?? "—"}</div>
              <div className="text-[10px] text-slate-500">{l}</div>
            </div>
          ))}
        </div>
      )}
      {failed && <div className="mt-4 text-sm text-amber-300 bg-amber-500/10 border border-amber-500/30 rounded-lg p-3" data-testid="scan-error">{session.error}</div>}
      {!done && msgs.length > 0 && (
        <div className="mt-4 text-xs text-slate-400 font-num" data-testid="scan-current-message">› {msgs[msgs.length - 1].msg}</div>
      )}
      {done && <div className="mt-3 text-[11px] text-slate-500">开始 {dt(session.started_at)} · 完成 {dt(session.completed_at)}</div>}
    </div>
  );
}
