import { isNum, TODAY_STATUS_STYLE, QUOTE_TYPE_STYLE, dt } from "@/lib/format";

export const StatusPill = ({ status, label, testid }) => (
  <span data-testid={testid}
    className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full border text-xs font-medium ${TODAY_STATUS_STYLE[status] || TODAY_STATUS_STYLE.NO_VALID_OPPORTUNITY}`}>
    <span className="w-1.5 h-1.5 rounded-full bg-current" />
    {label}
  </span>
);

export const QuoteBadge = ({ type, label, testid }) => (
  <span data-testid={testid} className={`inline-flex px-2 py-0.5 rounded border text-[11px] ${QUOTE_TYPE_STYLE[type] || QUOTE_TYPE_STYLE.PREV_CLOSE}`}>
    {label || type}
  </span>
);

export const ScoreBar = ({ label, value, inverse = false, testid }) => {
  const v = isNum(value) ? Math.max(0, Math.min(100, value)) : 0;
  const good = inverse ? 100 - v : v;
  const color = good >= 65 ? "bg-red-400" : good >= 45 ? "bg-amber-400" : "bg-slate-500";
  return (
    <div data-testid={testid} className="space-y-1">
      <div className="flex justify-between text-xs">
        <span className="text-slate-400">{label}</span>
        <span className="font-num text-slate-200">{isNum(value) ? value.toFixed(0) : "—"}</span>
      </div>
      <div className="h-1.5 rounded-full bg-slate-800 overflow-hidden">
        <div className={`h-full ${color} transition-[width] duration-700`} style={{ width: `${v}%` }} />
      </div>
    </div>
  );
};

export const Stat = ({ label, value, sub, className = "", testid }) => (
  <div data-testid={testid} className={`min-w-0 ${className}`}>
    <div className="eyebrow">{label}</div>
    <div className="font-num text-lg text-slate-100 mt-1 truncate">{value}</div>
    {sub && <div className="text-xs text-slate-500 mt-0.5 truncate">{sub}</div>}
  </div>
);

export const DataStamp = ({ item, testid }) => (
  <div data-testid={testid} className="flex flex-wrap items-center gap-2 text-[11px] text-slate-500">
    <QuoteBadge type={item.quote_type} label={item.quote_type_label} />
    <span>行情时间 <span className="font-num text-slate-300">{dt(item.quote_time)}</span></span>
    <span>来源 {item.data_source}</span>
  </div>
);

export const Empty = ({ title, children, testid }) => (
  <div data-testid={testid} className="panel p-10 text-center rise">
    <div className="text-lg text-slate-100 font-semibold">{title}</div>
    {children && <div className="text-sm text-slate-400 mt-2 max-w-xl mx-auto leading-relaxed">{children}</div>}
  </div>
);

export const Section = ({ title, extra, children, className = "", testid }) => (
  <section data-testid={testid} className={`panel p-5 md:p-6 ${className}`}>
    <div className="flex items-center justify-between gap-3 mb-4">
      <h2 className="text-base md:text-lg font-semibold text-slate-100">{title}</h2>
      {extra}
    </div>
    {children}
  </section>
);

