import { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { Database, Cpu } from "lucide-react";
import { api } from "@/lib/api";

export default function ReadinessBanner() {
  const [d, setD] = useState(null);
  useEffect(() => {
    Promise.all([api.get("/market/data-status"), api.get("/models/status")])
      .then(([a, b]) => setD({ data: a.data, model: b.data })).catch(() => {});
  }, []);
  if (!d) return null;
  const bf = d.data.backfill_job;
  const cov = d.data.history_coverage || {};
  const tj = d.model.train_job;
  const modelReady = !!d.model.active_version;
  const bfRunning = bf?.status === "RUNNING";
  if (modelReady && !bfRunning) return null;
  return (
    <div className="panel p-4 flex flex-col sm:flex-row gap-3 sm:items-center text-xs rise" data-testid="readiness-banner">
      <div className="flex items-center gap-2 text-slate-300">
        <Database className="w-4 h-4 text-blue-300" />
        {bfRunning ? <>历史库建设中：<span className="font-num">{bf.message}</span></> : <>历史库已覆盖 <b className="font-num">{cov.n || 0}</b> 只股票</>}
      </div>
      <div className="flex items-center gap-2 text-slate-300">
        <Cpu className="w-4 h-4 text-red-300" />
        {modelReady ? <>模型 <span className="font-num">{d.model.active_version}</span></> :
          tj?.status === "RUNNING" ? <>模型训练中：{tj.message}</> : <>模型尚未训练（历史库建成后自动训练）</>}
      </div>
      <Link to="/models" data-testid="readiness-models-link" className="sm:ml-auto text-blue-300 hover:text-blue-200">查看进度 →</Link>
    </div>
  );
}
