import axios from "axios";

const API = `${process.env.REACT_APP_BACKEND_URL}/api`;

function clientId() {
  let id = localStorage.getItem("ashare_client_id");
  if (!id) {
    id = (crypto.randomUUID ? crypto.randomUUID() : `c${Date.now()}${Math.random().toString(16).slice(2)}`);
    localStorage.setItem("ashare_client_id", id);
  }
  return id;
}

export const api = axios.create({ baseURL: API, timeout: 60000 });
api.interceptors.request.use((cfg) => {
  cfg.headers["X-Client-Id"] = clientId();
  return cfg;
});

export const errMsg = (e) => e?.response?.data?.detail || e?.message || "请求失败";
export const exportUrl = () => `${API}/history/export`;
export const getClientId = clientId;
