import { useMemo, useState } from "react";
import { ComposedChart, Line, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, ReferenceArea, CartesianGrid, Brush, Cell } from "recharts";
import { HelpCircle, X, Info } from "lucide-react";

const RANGES = [["1月", 22], ["3月", 66], ["6月", 130], ["1年", 250], ["全部", 0]];
export const SERIES = [
  { key: "close", name: "收盘价", color: "#F1F5F9", tip: "每天收盘时的成交价格，连成一条线，看整体涨跌方向。" },
  { key: "ma5", name: "5 日均线", color: "#F59E0B", tip: "最近 5 个交易日收盘价的平均值，反映一周左右的短期趋势。" },
  { key: "ma20", name: "20 日均线", color: "#A78BFA", tip: "最近 20 个交易日（约一个月）的平均价，价格在它上方通常说明短期偏强。" },
  { key: "ma60", name: "60 日均线", color: "#22D3EE", tip: "最近 60 个交易日（约一个季度）的平均价，用来判断中期位置高低。" },
  { key: "volume", name: "成交量", color: "#EF4444", tip: "柱子越高，当天买卖越活跃。红色=当日上涨，绿色=当日下跌。" },
];
const tip = { contentStyle: { background: "#0F1520", border: "1px solid #222D3D", borderRadius: 8, fontSize: 12 }, labelStyle: { color: "#94A3B8" } };
const f2 = (v) => (typeof v === "number" ? v.toFixed(2) : "—");

export function HowToRead({ onClose }) {
  return (
    <div className="rounded-xl border border-blue-500/30 bg-blue-500/5 p-4 text-xs text-slate-300 space-y-2 relative" data-testid="chart-help-card">
      <button onClick={onClose} className="absolute right-3 top-3 text-slate-500 hover:text-slate-200" data-testid="chart-help-close" aria-label="关闭"><X className="w-4 h-4" /></button>
      <div className="text-sm font-semibold text-slate-100">如何看这张图</div>
      <p>白线是每天的收盘价；黄、紫、青三条线是 5 日、20 日、60 日的平均价格，用来看短、中期趋势。下方柱子是成交量，红色表示当天上涨、绿色表示下跌。</p>
      <p><span className="text-red-300">红色半透明区域</span>是今日参考买入区间，<span className="text-blue-300">蓝色虚线区域</span>是下一交易日参考买入区间。它们只是参考价格范围，不保证会达到，也不保证成交或上涨。</p>
      <p>拖动下方滑块可以缩放和平移时间；点击图中任意一天可查看当天价格；点击图例可以隐藏或显示某条线。</p>
    </div>
  );
}

function Legend({ hidden, toggle, point, open, setOpen }) {
  return (
    <div className="flex flex-wrap gap-2" data-testid="chart-legend">
      {SERIES.map((s) => (
        <div key={s.key} className="flex items-center">
          <button onClick={() => toggle(s.key)} data-testid={`legend-${s.key}`}
            className={`flex items-center gap-1.5 text-[11px] px-2 py-1 rounded-l-md border border-[#222D3D] transition-opacity ${hidden[s.key] ? "opacity-40" : ""}`}>
            <span className="w-3 h-1.5 rounded-sm" style={{ background: s.key === "volume" ? "linear-gradient(90deg,#EF4444 50%,#10B981 50%)" : s.color }} />
            <span className="text-slate-300">{s.name}</span>
            <span className="font-num text-slate-100">{s.key === "volume" ? (point?.volume ? `${Math.round(point.volume / 100).toLocaleString()}手` : "—") : f2(point?.[s.key])}</span>
          </button>
          <button onClick={() => setOpen(open === s.key ? null : s.key)} data-testid={`legend-info-${s.key}`} aria-label="说明"
            className="px-1.5 py-1 rounded-r-md border border-l-0 border-[#222D3D] text-slate-500 hover:text-slate-200"><Info className="w-3 h-3" /></button>
        </div>
      ))}
      {open && <div className="w-full text-[11px] text-slate-400" data-testid="legend-explain">{SERIES.find((s) => s.key === open)?.tip}</div>}
    </div>
  );
}

function ZoneChips({ zones, active, setActive }) {
  return (
    <div className="flex flex-wrap gap-2 text-[11px]">
      {zones.map((z) => (
        <button key={z.id} onClick={() => setActive(active === z.id ? null : z.id)} data-testid={`zone-chip-${z.id}`}
          className={`px-2 py-1 rounded-md border ${z.id === "today" ? "border-red-500/50 text-red-200 bg-red-500/10" : "border-dashed border-blue-500/60 text-blue-200 bg-blue-500/10"}`}>
          {z.title} {f2(z.lo)}–{f2(z.hi)}
        </button>
      ))}
    </div>
  );
}

export default function StockChart({ bars, today, tomorrow, strategyFormal = true }) {
  const [range, setRange] = useState(66);
  const [hidden, setHidden] = useState({});
  const [sel, setSel] = useState(null);
  const [open, setOpen] = useState(null);
  const [zoneInfo, setZoneInfo] = useState(null);
  const [help, setHelp] = useState(() => !localStorage.getItem("ashare_chart_help_seen"));
  const data = useMemo(() => {
    const b = range ? bars.slice(-range) : bars;
    return b.map((x, i) => ({ ...x, up: i === 0 ? x.close >= (x.open ?? x.close) : x.close >= b[i - 1].close }));
  }, [bars, range]);
  const zones = [
    today?.today_buy_zone_low && { id: "today", title: strategyFormal ? "今日参考买入区间" : "今日观察参考区间", lo: today.today_buy_zone_low, hi: today.today_buy_zone_high, day: today.trade_date || bars[bars.length - 1]?.trade_date },
    tomorrow?.tomorrow_buy_zone_low && { id: "tomorrow", title: strategyFormal ? "下一交易日参考买入区间" : "下一交易日观察参考区间", lo: tomorrow.tomorrow_buy_zone_low, hi: tomorrow.tomorrow_buy_zone_high, day: tomorrow.next_trading_day },
  ].filter(Boolean);
  if (!data.length) return null;
  const lows = data.map((b) => b.low).concat(zones.map((z) => z.lo));
  const highs = data.map((b) => b.high).concat(zones.map((z) => z.hi));
  const lo = Math.min(...lows), hi = Math.max(...highs);
  const vmax = Math.max(...data.map((b) => b.volume || 0));
  const point = sel || data[data.length - 1];
  const zi = zones.find((z) => z.id === zoneInfo);
  const closeHelp = () => { localStorage.setItem("ashare_chart_help_seen", "1"); setHelp(false); };
  return (
    <div className="space-y-3" data-testid="stock-chart">
      {help && <HowToRead onClose={closeHelp} />}
      <div className="flex flex-wrap items-center justify-between gap-2">
        <div className="flex gap-1" data-testid="range-selector">
          {RANGES.map(([l, n]) => (
            <button key={l} onClick={() => { setRange(n); setSel(null); }} data-testid={`range-${l}`}
              className={`text-[11px] px-2.5 py-1 rounded-md border transition-colors ${range === n ? "border-blue-500/60 bg-blue-500/10 text-blue-100" : "border-[#222D3D] text-slate-400 hover:text-slate-200"}`}>{l}</button>
          ))}
        </div>
        <button onClick={() => setHelp(true)} data-testid="chart-help-open" className="text-slate-400 hover:text-slate-100 flex items-center gap-1 text-[11px]"><HelpCircle className="w-4 h-4" /> 如何看图</button>
      </div>
      <Legend hidden={hidden} toggle={(k) => setHidden((h) => ({ ...h, [k]: !h[k] }))} point={point} open={open} setOpen={setOpen} />
      <div className="text-[11px] text-slate-400 font-num" data-testid="chart-selected-point">
        {point.trade_date} · 开 {f2(point.open)} 高 {f2(point.high)} 低 {f2(point.low)} 收 {f2(point.close)}{sel ? "" : "（最新）"}
      </div>
      <div className="h-80 sm:h-96" data-testid="price-chart">
        <ResponsiveContainer width="100%" height="100%">
          <ComposedChart data={data} margin={{ top: 8, right: 4, left: -8, bottom: 0 }} onClick={(e) => { const p = data.find((x) => x.trade_date === e?.activeLabel) || data[Number(e?.activeIndex ?? e?.activeTooltipIndex)]; if (p) setSel(p); }}>
            <CartesianGrid stroke="#1A2332" vertical={false} />
            <XAxis dataKey="trade_date" tick={{ fill: "#64748B", fontSize: 10 }} tickFormatter={(d) => d.slice(2)} minTickGap={36} />
            <YAxis yAxisId="p" orientation="right" domain={[lo * 0.97, hi * 1.02]} tick={{ fill: "#64748B", fontSize: 10 }} tickFormatter={(v) => v.toFixed(2)} width={52} allowDataOverflow />
            <YAxis yAxisId="v" hide domain={[0, vmax * 4]} />
            <Tooltip {...tip} formatter={(v, n) => (n === "成交量" ? [`${Math.round(v / 100).toLocaleString()} 手`, n] : [f2(v), n])} />
            {!hidden.volume && (
              <Bar yAxisId="v" dataKey="volume" name="成交量" isAnimationActive={false}>
                {data.map((x, i) => <Cell key={i} fill={x.up ? "#EF4444" : "#10B981"} fillOpacity={0.55} />)}
              </Bar>
            )}
            {zones.map((z) => (
              <ReferenceArea key={z.id} yAxisId="p" y1={z.lo} y2={z.hi} ifOverflow="extendDomain" onClick={() => setZoneInfo(z.id)}
                fill={z.id === "today" ? "#EF4444" : "#3B82F6"} fillOpacity={0.14} stroke={z.id === "today" ? "#EF4444" : "#60A5FA"}
                strokeOpacity={0.8} strokeDasharray={z.id === "today" ? undefined : "5 4"} style={{ cursor: "pointer" }}
                label={{ value: `${z.id === "today" ? "今日" : "下一日"} ${f2(z.lo)}–${f2(z.hi)}`, position: z.id === "today" ? "insideTopRight" : "insideBottomLeft", fill: z.id === "today" ? "#FCA5A5" : "#93C5FD", fontSize: 10 }} />
            ))}
            {SERIES.filter((s) => s.key !== "volume" && !hidden[s.key]).map((s) => (
              <Line key={s.key} yAxisId="p" type="monotone" dataKey={s.key} name={s.name} stroke={s.color} dot={false}
                strokeWidth={s.key === "close" ? 1.8 : 1.1} isAnimationActive={false} connectNulls />
            ))}
            <Brush dataKey="trade_date" height={32} stroke="#60A5FA" fill="#0B1019" travellerWidth={14} tickFormatter={(d) => d.slice(2)} />
          </ComposedChart>
        </ResponsiveContainer>
      </div>
      <ZoneChips zones={zones} active={zoneInfo} setActive={setZoneInfo} />
      {zi && (
        <div className="text-xs text-slate-300 rounded-lg border border-[#1E2838] bg-[#0F1520] p-3" data-testid="zone-detail">
          <b>{zi.title}</b>（{zi.day || "—"}）：最低 <span className="font-num">{f2(zi.lo)}</span>，最高 <span className="font-num">{f2(zi.hi)}</span>。
          这是参考价格范围，不保证会达到，也不保证成交或上涨。
        </div>
      )}
      <p className="text-[11px] text-slate-500">
        <span className="text-red-300">红色区域</span>：今日参考区间；<span className="text-blue-300">蓝色虚线区域</span>：下一交易日参考区间。两者都是参考价格范围，不保证会达到、成交或上涨。图中价格为真实不复权行情，未做任何修改。
      </p>
    </div>
  );
}
