import { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import { ArrowLeft, RefreshCw } from "lucide-react";
import { api, errMsg } from "@/lib/api";
import { price, pct, pctRaw, tclass, score, yuan } from "@/lib/format";
import { Section, ScoreBar, StatusPill, DataStamp, Empty, Disclaimer, Stat } from "@/components/common";
import StockChart from "@/charts/StockChart";
import { StatusBadge } from "@/components/StrategyStatus";
import { MoneyLine, consensusText } from "@/components/CandidateCard";

const SCORE_ROWS = [["low_position_score", "低位识别"], ["downtrend_exhaustion_score", "下跌动能衰减"], ["stabilization_score", "企稳识别"],
  ["rebound_potential_score", "反弹潜力"], ["liquidity_score", "流动性"], ["risk_score", "风险（越低越好）", true]];
const MODEL_NAMES = { xgb: "XGBoost", lgbm: "LightGBM", hgb: "HistGBDT", rf: "随机森林", et: "ExtraTrees", lr: "逻辑回归" };

function ZoneBlock({ title, status, label, low, high, conds, basis, testid }) {
  return (
    <div className="rounded-xl bg-[#0F1520] border border-[#1E2838] p-4 space-y-3" data-testid={testid}>
      <div className="flex items-center justify-between gap-2"><span className="eyebrow">{title}</span><StatusPill status={status} label={label} /></div>
      <div className="font-num text-2xl text-slate-100">{price(low)} <span className="text-slate-600">–</span> {price(high)}</div>
      <ul className="text-xs text-slate-300 space-y-1">{(conds || []).map((c) => <li key={c}>› {c}</li>)}</ul>
      <ul className="text-[11px] text-slate-500 space-y-1 border-t border-[#1E2838] pt-2">{(basis || []).map((b) => <li key={b}>· {b}</li>)}</ul>
    </div>
  );
}

function ModelBlock({ a }) {
  const m = a.model || {};
  if (!m.available) return <p className="text-sm text-slate-400">模型尚未训练完成，暂无模型预测。</p>;
  return (
    <div className="space-y-4">
      {(m.schema >= 2 ? [1, 3, 5] : [3, 5]).map((h) => (
        <div key={h} data-testid={`model-horizon-${h}`}>
          <div className="flex justify-between text-sm">
            <span className="text-slate-300">未来 {h} 个交易日{m[`grade_${h}d`] ? `（${m[`grade_${h}d`]} 级 · 可信度${m[`credibility_${h}d`]}）` : h === 1 ? "（仅作参考）" : ""} {m[`calibrated_${h}d`] && m[`prob_${h}d`] != null ? "正收益概率" : "：概率校准未通过，不显示概率"}</span>
            <span className="font-num text-red-300">{m[`calibrated_${h}d`] && m[`prob_${h}d`] != null ? pct(m[`prob_${h}d`], 1) : "—"}</span>
          </div>
          {m[`accuracy_${h}d`] && <div className="text-[11px] text-slate-400" data-testid={`model-accuracy-${h}`}>{m[`grade_${h}d`] === "C" ? "不推荐采纳 · " : ""}验收期胜率 {pct(m[`accuracy_${h}d`].win_rate, 0)}（{m[`accuracy_${h}d`].trades} 笔），平均每笔扣费后 {pct(m[`accuracy_${h}d`].mean_trade_net_return, 2, true)}</div>}
          {m[`consensus_${h}d`] && <div className="text-[11px] text-slate-400" data-testid={`model-consensus-${h}`}>{consensusText(m[`consensus_${h}d`])}（看好 = 当日全市场前 30%）</div>}
          <div className="text-[11px] text-slate-500">历史基准 {pct(m[`base_rate_${h}d`], 1)} · 预测收益 {pct(m[`pred_ret_${h}d`], 2, true)} · 模型分歧 {pct(m[`dispersion_${h}d`], 1)}</div>
          <div className="flex flex-wrap gap-2 mt-2">
            {Object.entries(m[`per_model_${h}d`] || {}).map(([k, v]) => (
              <span key={k} className="text-[11px] px-2 py-1 rounded bg-slate-800 text-slate-300">{MODEL_NAMES[k] || k} 原始分 <b className="font-num">{v?.toFixed(3)}</b></span>
            ))}
          </div>
        </div>
      ))}
      <div className="text-[11px] text-slate-500">模型版本 <span className="font-num">{m.version}</span> · 同日全市场排名 {m.rank_pct != null ? `前 ${Math.max(1, Math.round((1 - m.rank_pct) * 100))}%` : "—"}</div>
    </div>
  );
}

function withLive(bars, a) {
  const d = (a.quote_time || "").slice(0, 10);
  if (!bars.length || !d || d <= bars[bars.length - 1].trade_date || !a.price) return bars;
  return [...bars, { trade_date: d, open: a.open, high: a.high, low: a.low, close: a.price, volume: 0 }];
}

function Conclusion({ a, formal }) {
  const alerts = a.plan_alerts || [];
  const al = a.allocation;
  return (
    <div className="panel p-5 space-y-3" data-testid="stock-conclusion">
      <div className="flex flex-wrap items-center gap-2">
        <span className="eyebrow">结论</span>
        {a.strategy_status && <StatusBadge status={a.strategy_status.status} label={a.strategy_status.label} testid="stock-strategy-status" />}
        <span className="text-sm text-slate-100" data-testid="stock-conclusion-text">
          {a.is_candidate ? (formal ? (a.strategy_status?.status === "CONDITIONAL" ? "本次有条件候选：证据仍不充分，建议金额仅供参考，请结合风险提示判断" : "本次正式候选：可考虑在参考区间内、买入条件满足时买入") : "进入本次观察名单（尚未证明优于对照组，不提供建议金额）") : "未进入本次名单"}
        </span>
      </div>
      {alerts.length > 0 && <div className="text-xs text-amber-200 bg-amber-500/10 border border-amber-500/25 rounded-lg p-3" data-testid="stock-plan-alerts">暂不建议按原计划买入：{alerts.join("；")}。请刷新最新行情后重新评估。</div>}
      <MoneyLine item={a} formal={formal} />
      {formal && al?.why?.length > 0 && <ul className="text-[11px] text-slate-400 space-y-1" data-testid="allocation-why">{al.why.map((w) => <li key={w}>· {w}</li>)}</ul>}
    </div>
  );
}

export default function StockDetailPage() {
  const { code } = useParams();
  const navigate = useNavigate();
  const [a, setA] = useState(null);
  const [hist, setHist] = useState(null);
  const [err, setErr] = useState(null);
  const [loading, setLoading] = useState(false);
  const load = (fresh = false) => {
    setLoading(true);
    setErr(null);
    api.get(`/stock/${code}/analysis`, { params: { fresh } }).then((r) => setA(r.data)).catch((e) => setErr(errMsg(e))).finally(() => setLoading(false));
  };
  const refresh = () => {
    setLoading(true);
    setErr(null);
    api.post(`/stock/${code}/refresh`, null, { params: { horizon: a?.horizon } }).then((r) => setA(r.data)).catch((e) => setErr(errMsg(e))).finally(() => setLoading(false));
  };
  useEffect(() => {
    load();
    api.get(`/stock/${code}/history`, { params: { days: 3000 } }).then((r) => setHist(r.data)).catch(() => {});
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [code]);
  if (err && !a) return <Empty title="无法显示该股票" testid="stock-error">{err}</Empty>;
  if (!a) return <div className="panel h-96 animate-pulse" data-testid="stock-loading" />;
  const pos = a.position || {};
  const formal = ["FORMAL", "CONDITIONAL"].includes(a.strategy_status?.status || "FORMAL");
  return (
    <div className="space-y-6" data-testid="stock-detail-page">
      <button onClick={() => navigate(-1)} className="text-xs text-slate-400 hover:text-slate-200 flex items-center gap-1" data-testid="stock-back"><ArrowLeft className="w-3.5 h-3.5" /> 返回</button>
      <div className="flex flex-wrap items-end justify-between gap-4 rise">
        <div>
          <div className="text-xs text-slate-500"><span className="font-num text-sky-400 tracking-wider">{a.stock_code}</span> · {a.exchange_label} · {a.board_label}{a.industry ? ` · ${a.industry}` : ""}</div>
          <h1 className="text-3xl sm:text-4xl font-bold text-slate-50 mt-1" data-testid="stock-name">{a.stock_name}</h1>
          <div className="mt-2"><DataStamp item={a} testid="stock-data-stamp" /></div>
        </div>
        <div className="text-right">
          <div className={`font-num text-4xl font-bold ${tclass(a.change_pct)}`} data-testid="stock-price">{price(a.price)}</div>
          <div className={`font-num text-sm ${tclass(a.change_pct)}`}>{pctRaw(a.change_pct)}</div>
          <button onClick={refresh} disabled={loading} data-testid="stock-refresh-quote-btn" className="mt-2 text-xs px-3 py-1.5 rounded-md border border-blue-500/40 text-blue-200 hover:bg-blue-500/10 inline-flex items-center gap-1.5 disabled:opacity-50">
            <RefreshCw className={`w-3.5 h-3.5 ${loading ? "animate-spin" : ""}`} /> 刷新该股最新行情
          </button>
        </div>
      </div>
      {a.note && <div className="text-[11px] text-slate-500" data-testid="stock-note">{a.note}</div>}
      {err && <div className="text-xs text-amber-200" data-testid="stock-refresh-error">{err}</div>}
      <Conclusion a={a} formal={formal} />
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4 panel p-5">
        <Stat label="综合评分" value={score(a.overall_candidate_score)} sub={a.is_candidate ? "本次候选" : "未进入候选"} testid="stock-overall" />
        <Stat label="资金上限可买" value={pos.affordable ? `${pos.estimated_affordable_quantity} 股` : "—"} sub={a.position ? (pos.affordable ? `约 ${yuan(pos.estimated_purchase_cost)}` : pos.reason) : "未填写可用资金"} />
        <Stat label="一手所需" value={yuan(a.lot_info?.one_lot_cost)} sub={a.lot_info ? `${a.lot_info.min_lot} 股，含估算费用` : ""} />
        <Stat label="涨停 / 跌停" value={`${price(a.limit_up)} / ${price(a.limit_down)}`} sub={a.limit_pct ? `涨跌幅限制 ${pct(a.limit_pct, 0)}` : "无涨跌幅限制"} />
      </div>
      {!a.is_candidate && a.rejections?.length > 0 && (
        <div className="text-xs text-slate-300 panel p-4" data-testid="stock-rejections">未进入候选的原因：{a.rejections.join("、")}</div>
      )}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <ZoneBlock testid="detail-today-zone" title={formal ? "今日参考买入区间" : "今日观察参考区间"} status={a.today.status} label={a.today.status_label} low={a.today.today_buy_zone_low}
          high={a.today.today_buy_zone_high} conds={a.today.today_entry_conditions} basis={a.today.basis} />
        <ZoneBlock testid="detail-tomorrow-zone" title={`下一交易日（${a.tomorrow.next_trading_day || "—"}）${formal ? "参考买入区间" : "观察参考区间"}`} status={a.tomorrow.status} label={a.tomorrow.status_label}
          low={a.tomorrow.tomorrow_buy_zone_low} high={a.tomorrow.tomorrow_buy_zone_high} conds={a.tomorrow.tomorrow_entry_conditions} basis={a.tomorrow.basis} />
      </div>
      <Section title={formal ? "入选依据与主要风险" : "观察依据与主要风险"} testid="stock-reasons">
        <div className="grid md:grid-cols-2 gap-6 text-sm">
          <ul className="space-y-2 text-slate-300">{a.reasons.map((r) => <li key={r}>✓ {r}</li>)}</ul>
          <ul className="space-y-2 text-amber-200/90">{a.risks.map((r) => <li key={r}>! {r}</li>)}</ul>
        </div>
      </Section>
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
        <Section title="价格走势（不复权）" className="lg:col-span-8" testid="stock-chart-section">
          {hist ? <StockChart bars={withLive(hist.bars, a)} today={a.today} tomorrow={a.tomorrow} strategyFormal={formal} /> : <div className="h-72 animate-pulse" />}
        </Section>
        <Section title="识别结果" className="lg:col-span-4" testid="stock-scores">
          <div className="space-y-3">{SCORE_ROWS.map(([k, l, inv]) => <ScoreBar key={k} label={l} value={a.scores[k]} inverse={inv} testid={`score-${k}`} />)}</div>
        </Section>
      </div>
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <Section title="模型预测" testid="stock-model"><ModelBlock a={a} /></Section>
        <Section title="数据质量" testid="stock-quality">
          <div className="grid grid-cols-3 gap-3">
            <Stat label="行情质量" value={score(a.quality.quote_quality_score)} />
            <Stat label="历史质量" value={score(a.quality.history_quality_score)} />
            <Stat label="来源一致性" value={score(a.quality.source_consistency_score)} />
          </div>
          <div className="text-[11px] text-slate-500 mt-3 space-y-1">
            <div>{a.quality.consistency_note}</div>
            <div>历史日线 {a.quality.history_bars} 根（约 {a.quality.history_years} 年）{a.quality.missing_fields?.length ? ` · 缺失字段：${a.quality.missing_fields.join(", ")}` : ""}</div>
          </div>
        </Section>
      </div>
      <Disclaimer />
    </div>
  );
}
