import { useEffect, useState } from "react";
import { Play, ChevronDown, Loader2 } from "lucide-react";
import { toast } from "sonner";
import { Input } from "@/components/ui/input";
import { Switch } from "@/components/ui/switch";
import { Checkbox } from "@/components/ui/checkbox";
import { useScan } from "@/hooks/useScan";
import { errMsg } from "@/lib/api";

const COST_FIELDS = [
  ["commission_rate", "佣金费率", "0.00025"], ["min_commission", "最低佣金(元)", "5"],
  ["stamp_tax_sell", "卖出印花税", "0.0005"], ["transfer_fee", "过户费率", "0.00001"], ["slippage", "滑点", "0.001"],
];
const SWITCHES = [
  ["exclude_st", "排除 ST 股票", "名称含 ST 的股票不参与分析"],
  ["exclude_high_risk", "排除高风险股票", "风险评分 > 60 的不入选（关闭后放宽到 80）"],
  ["allow_high_vol", "允许高波动股票", "关闭时排除年化波动 > 65% 或日均振幅 > 6% 的股票"],
];
const num = (v) => (v === "" || v == null ? null : Number(v));
const clean = (v) => v.replace(/[^\d.]/g, "");

const MoneyInput = ({ label, hint, value, onChange, testid }) => (
  <div>
    <label className="eyebrow">{label}</label>
    <div className="relative mt-2">
      <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-500 font-num">¥</span>
      <Input data-testid={testid} inputMode="decimal" value={value} placeholder="选填" onChange={(e) => onChange(clean(e.target.value))}
        className="pl-9 h-12 text-lg font-num bg-[#0F1520] border-[#222D3D]" />
    </div>
    <p className="text-[11px] text-slate-500 mt-1.5 leading-relaxed">{hint}</p>
  </div>
);

function PriceRange({ f, set }) {
  return (
    <div>
      <label className="eyebrow">可接受的股价范围（元）</label>
      <div className="flex items-center gap-2 mt-2">
        <Input data-testid="price-min-input" inputMode="decimal" placeholder="最低价" disabled={f.price_unlimited} value={f.price_min}
          onChange={(e) => set("price_min", clean(e.target.value))} className="h-11 font-num bg-[#0F1520] border-[#222D3D]" />
        <span className="text-slate-600">–</span>
        <Input data-testid="price-max-input" inputMode="decimal" placeholder="最高价" disabled={f.price_unlimited} value={f.price_max}
          onChange={(e) => set("price_max", clean(e.target.value))} className="h-11 font-num bg-[#0F1520] border-[#222D3D]" />
      </div>
      <label className="flex items-center gap-2 mt-2.5 text-xs text-slate-300 cursor-pointer">
        <Checkbox data-testid="price-unlimited-checkbox" checked={f.price_unlimited} onCheckedChange={(v) => set("price_unlimited", !!v)} />
        无特别限制，由系统判断
      </label>
    </div>
  );
}

function Switches({ f, set }) {
  return (
    <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
      {SWITCHES.map(([k, label, hint]) => (
        <label key={k} className="rounded-lg border border-[#1E2838] bg-[#0F1520] p-3 flex items-start justify-between gap-3 cursor-pointer">
          <span><span className="text-sm text-slate-200 block">{label}</span><span className="text-[11px] text-slate-500 leading-snug block mt-0.5">{hint}</span></span>
          <Switch data-testid={`switch-${k}`} checked={f[k]} onCheckedChange={(v) => set(k, v)} />
        </label>
      ))}
    </div>
  );
}

function Costs({ costs, setCosts }) {
  const [open, setOpen] = useState(false);
  return (
    <div>
      <button type="button" data-testid="toggle-cost-settings" onClick={() => setOpen(!open)} className="flex items-center gap-1 text-xs text-slate-400 hover:text-slate-200">
        <ChevronDown className={`w-3.5 h-3.5 transition-transform ${open ? "rotate-180" : ""}`} /> 交易成本设置（未填写则使用标明的默认估算参数）
      </button>
      {open && (
        <div className="grid grid-cols-2 md:grid-cols-5 gap-3 mt-3" data-testid="cost-settings">
          {COST_FIELDS.map(([k, label, ph]) => (
            <div key={k}>
              <div className="text-[11px] text-slate-500 mb-1">{label}</div>
              <Input data-testid={`cost-${k}`} value={costs[k] ?? ""} placeholder={`默认 ${ph}`} inputMode="decimal"
                onChange={(e) => setCosts({ ...costs, [k]: e.target.value })} className="h-9 font-num text-sm bg-[#0F1520] border-[#222D3D]" />
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

const DEFAULTS = { capital: "", planned_amount: "", price_min: "", price_max: "", price_unlimited: false, exclude_st: true,
  exclude_high_risk: true, allow_high_vol: false, horizon: 5 };

function validate(f) {
  const cap = num(f.capital), plan = num(f.planned_amount);
  if (cap !== null && !(cap > 0)) return "可用资金必须大于 0（不填可留空）";
  if (plan !== null && !(plan > 0)) return "计划投入金额必须大于 0（不填可留空）";
  if (cap && plan && plan > cap) return "计划投入金额不能超过可用资金";
  if (!f.price_unlimited && f.price_min === "" && f.price_max === "") return "请填写股价范围，或勾选“无特别限制，由系统判断”";
  if (!f.price_unlimited && f.price_min !== "" && f.price_max !== "" && num(f.price_min) > num(f.price_max)) return "最低价不能高于最高价";
  return null;
}

export default function AnalysisForm({ onHorizon, sessionHorizon }) {
  const { start, running } = useScan();
  const saved = JSON.parse(localStorage.getItem("ashare_form_v2") || "{}");
  const [f, setF] = useState({ ...DEFAULTS, ...saved.f });
  const [costs, setCosts] = useState(saved.costs || {});
  const [busy, setBusy] = useState(false);
  const set = (k, v) => setF((x) => ({ ...x, [k]: v }));
  useEffect(() => { if (sessionHorizon) set("horizon", sessionHorizon); }, [sessionHorizon]);
  useEffect(() => { onHorizon?.(f.horizon); }, [f.horizon, onHorizon]);

  const submit = async (e) => {
    e.preventDefault();
    const bad = validate(f);
    if (bad) return toast.error(bad);
    const c = {};
    Object.entries(costs).forEach(([k, v]) => { if (v !== "" && v != null) c[k] = Number(v); });
    localStorage.setItem("ashare_form_v2", JSON.stringify({ f, costs }));
    setBusy(true);
    try {
      await start({ capital: num(f.capital), planned_amount: num(f.planned_amount), price_min: f.price_unlimited ? null : num(f.price_min),
        price_max: f.price_unlimited ? null : num(f.price_max), price_unlimited: f.price_unlimited, exclude_st: f.exclude_st,
        exclude_high_risk: f.exclude_high_risk, allow_high_vol: f.allow_high_vol, horizon: f.horizon, costs: Object.keys(c).length ? c : null });
      toast.success("已开始全市场分析");
    } catch (err) {
      toast.error(errMsg(err));
    } finally {
      setBusy(false);
    }
  };

  return (
    <form onSubmit={submit} className="panel p-5 md:p-6 space-y-6 rise" data-testid="analysis-form">
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-5">
        <MoneyInput label="可用资金" testid="capital-input" value={f.capital} onChange={(v) => set("capital", v)}
          hint="不填也能选股，但不会显示可买数量，也不会假设你有某个金额" />
        <MoneyInput label="本次计划投入金额" testid="planned-amount-input" value={f.planned_amount} onChange={(v) => set("planned_amount", v)}
          hint="不填时，系统给出的金额会标明“系统建议，非用户授权金额”，且不会分配全部资金" />
      </div>
      <PriceRange f={f} set={set} />
      <Switches f={f} set={set} />
      <div className="flex flex-wrap items-center gap-3">
        <span className="eyebrow">关注周期</span>
        {[1, 3, 5].map((h) => (
          <button type="button" key={h} data-testid={`horizon-${h}`} onClick={() => set("horizon", h)}
            className={`px-4 py-1.5 rounded-full text-sm border transition-colors ${f.horizon === h ? "border-red-500/60 bg-red-500/10 text-red-200" : "border-[#222D3D] text-slate-400 hover:text-slate-200"}`}>
            未来 {h} 个交易日
          </button>
        ))}
        <span className="text-[11px] text-slate-500">各周期等级不同，见右侧策略状态</span>
      </div>
      <Costs costs={costs} setCosts={setCosts} />
      <button type="submit" disabled={running || busy} data-testid="start-analysis-btn"
        className="w-full h-14 rounded-xl bg-gradient-to-r from-red-600 to-red-500 text-white text-base font-semibold flex items-center justify-center gap-2 shadow-lg shadow-red-900/30 hover:brightness-110 active:scale-[0.99] transition-[filter,transform] disabled:opacity-50 disabled:cursor-not-allowed">
        {running || busy ? <Loader2 className="w-5 h-5 animate-spin" /> : <Play className="w-5 h-5" />}
        {running ? "分析进行中…" : "开始分析"}
      </button>
      <p className="text-[11px] text-slate-500 text-center">低位、动能衰竭、企稳、流动性、风险收益空间、市场环境都由系统自动判断；最多 5 只，没有就明确说没有</p>
    </form>
  );
}
