import { useEffect, useState } from "react";
import { toast } from "sonner";
import { RefreshCw, Play, Database } from "lucide-react";
import { api, errMsg } from "@/lib/api";
import { dt, pct } from "@/lib/format";
import { Section, Stat } from "@/components/common";
import { PageTitle } from "@/components/ResultsShared";
import { CalibrationChart } from "@/charts/Charts";
import { ModelV2Report, WalkForwardReport } from "@/components/ResearchReports";
import ModelV3Panel from "@/components/ModelV3Panel";

const JOB_LABEL = { backfill: "历史库更新", train: "第一版训练", backtest: "第一版回测", research: "第二版训练+滚动回测" };
const STATUS_LABEL = { RUNNING: "运行中", COMPLETED: "已完成", FAILED: "失败", INTERRUPTED: "已中断" };

function JobRow({ type, job, onRun, runLabel }) {
  return (
    <div className="flex flex-wrap items-center gap-3 py-3 border-t border-[#1E2838] first:border-0" data-testid={`job-${type}`}>
      <div className="w-24 text-sm text-slate-200">{JOB_LABEL[type]}</div>
      <div className="flex-1 min-w-[200px] text-xs text-slate-400">
        <span className={job?.status === "RUNNING" ? "text-blue-300" : job?.status === "FAILED" ? "text-amber-300" : "text-slate-300"}>{STATUS_LABEL[job?.status] || "未运行"}</span>
        {job?.progress != null && job.status === "RUNNING" && <span className="font-num"> · {job.progress}%</span>}
        <div className="text-[11px] text-slate-500 mt-0.5">{job?.message} {job?.finished_at ? `· ${dt(job.finished_at)}` : ""}</div>
      </div>
      <button onClick={onRun} disabled={job?.status === "RUNNING"} data-testid={`run-${type}-btn`}
        className="text-xs px-3 py-1.5 rounded-lg border border-[#222D3D] text-slate-300 hover:text-white hover:border-blue-500/50 disabled:opacity-40 flex items-center gap-1">
        <Play className="w-3 h-3" /> {runLabel}
      </button>
    </div>
  );
}

function MetricsTable({ title, rows }) {
  const cols = [["accuracy", "Accuracy"], ["precision", "Precision"], ["recall", "Recall"], ["f1", "F1"], ["roc_auc", "ROC-AUC"], ["brier", "Brier"], ["ece", "校准误差"]];
  return (
    <div className="overflow-x-auto">
      <div className="eyebrow mb-2">{title}</div>
      <table className="w-full text-xs min-w-[560px]">
        <thead className="text-slate-500 text-left"><tr><th className="py-1.5">模型</th>{cols.map(([, l]) => <th key={l}>{l}</th>)}</tr></thead>
        <tbody>
          {rows.map(([name, m]) => (
            <tr key={name} className="border-t border-[#1E2838]"><td className="py-1.5 text-slate-300">{name}</td>
              {cols.map(([k]) => <td key={k} className="font-num">{m?.[k] != null ? m[k] : "—"}</td>)}</tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

function TradeStats({ t, label }) {
  if (!t || !t.trades) return <div className="text-xs text-slate-500">{label}：无交易</div>;
  return (
    <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
      <Stat label="交易次数" value={t.trades} sub={t.fill_rate != null ? `成交率 ${pct(t.fill_rate, 0)}` : label} />
      <Stat label="正收益比例" value={pct(t.positive_ratio, 1)} />
      <Stat label="平均 / 中位收益" value={`${pct(t.mean_return, 2)} / ${pct(t.median_return, 2)}`} />
      <Stat label="最大回撤" value={t.max_drawdown_daily_equal_weight != null ? pct(t.max_drawdown_daily_equal_weight, 1) : "—"}
        sub={t.max_adverse_excursion_mean != null ? `平均不利 ${pct(t.max_adverse_excursion_mean, 1)} / 有利 ${pct(t.max_favorable_excursion_mean, 1)}` : ""} />
    </div>
  );
}

function Backtest({ bt }) {
  const [h, setH] = useState("5");
  if (!bt?.available) return <p className="text-sm text-slate-400" data-testid="backtest-unavailable">暂无回测结果（模型训练完成后自动运行）。</p>;
  const r = bt.result.horizons[h];
  return (
    <div className="space-y-6" data-testid="backtest-results">
      <div className="flex items-center gap-2 text-xs">
        {["3", "5"].map((x) => <button key={x} data-testid={`bt-horizon-${x}`} onClick={() => setH(x)} className={`px-3 py-1 rounded-full border ${h === x ? "border-red-500/60 text-red-200 bg-red-500/10" : "border-[#222D3D] text-slate-400"}`}>{x} 日</button>)}
        <span className="text-slate-500 ml-2">测试期 {bt.test_start} ~ {bt.test_end} · 模型 {bt.model_version} · {r.probability_calibrated ? "概率已通过校准检验" : "概率未通过校准检验（界面仅显示模型评分）"}</span>
      </div>
      <TradeStats t={r.strategy_trades_limit_entry} label="策略（限价买入）" />
      <div className="grid md:grid-cols-2 gap-6 text-xs text-slate-400">
        <div>对照 · 全部股票次日开盘买入：正收益比例 <b className="font-num text-slate-200">{pct(r.benchmark_all_stocks_next_open.positive_ratio, 1)}</b>，平均 <b className="font-num text-slate-200">{pct(r.benchmark_all_stocks_next_open.mean_return, 2)}</b></div>
        <div>对照 · 同信号次日开盘买入：正收益比例 <b className="font-num text-slate-200">{pct(r.strategy_next_open_entry.positive_ratio, 1)}</b>，交易 {r.strategy_next_open_entry.trades}</div>
      </div>
      <MetricsTable title="分类指标（测试集）" rows={[["集成模型", r.classification_ensemble], ...Object.entries(r.classification_per_model)]} />
      <div className="grid md:grid-cols-2 gap-6">
        <div><div className="eyebrow mb-2">概率校准曲线</div><CalibrationChart bins={r.classification_ensemble.calibration} /></div>
        <div className="space-y-4 text-xs">
          <div><div className="eyebrow mb-2">按年份</div>{Object.entries(r.by_year).map(([y, t]) => <div key={y} className="flex justify-between py-1 border-t border-[#1E2838]"><span>{y}</span><span className="font-num">{t.trades} 笔 · 正收益 {pct(t.positive_ratio, 0)} · 平均 {pct(t.mean_return, 2)}</span></div>)}</div>
          <div><div className="eyebrow mb-2">按市场环境</div>{Object.entries(r.by_regime).map(([y, t]) => <div key={y} className="flex justify-between py-1 border-t border-[#1E2838]"><span>{y}</span><span className="font-num">{t.trades} 笔 · 正收益 {pct(t.positive_ratio, 0)} · 平均 {pct(t.mean_return, 2)}</span></div>)}</div>
        </div>
      </div>
      <ul className="text-[11px] text-slate-500 space-y-1">{bt.result.assumptions.map((a) => <li key={a}>· {a}</li>)}</ul>
    </div>
  );
}

export default function ModelsPage() {
  const [ds, setDs] = useState(null);
  const [ms, setMs] = useState(null);
  const [bt, setBt] = useState(null);
  const load = () => {
    api.get("/market/data-status").then((r) => setDs(r.data)).catch(() => {});
    api.get("/models/status").then((r) => setMs(r.data)).catch(() => {});
    api.get("/backtest/results").then((r) => setBt(r.data)).catch(() => {});
  };
  useEffect(() => { load(); const t = setInterval(load, 10000); return () => clearInterval(t); }, []);
  const run = (path, label) => api.post(path).then((r) => { toast[r.data.started ? "success" : "info"](r.data.started ? `${label}已启动` : r.data.reason); load(); setTimeout(load, 2500); setTimeout(load, 8000); }).catch((e) => toast.error(errMsg(e)));
  const cov = ds?.history_coverage || {};
  const ens = ms?.ensemble;
  const qm = ens?.metrics?.quantile;
  return (
    <div className="space-y-6" data-testid="models-page">
      <div className="flex items-end justify-between gap-3">
        <PageTitle title="模型与数据" sub="本地历史库覆盖、后台任务、模型版本与按时间顺序划分的回测评估。" />
        <button onClick={load} data-testid="models-refresh" className="text-xs text-slate-400 hover:text-white flex items-center gap-1"><RefreshCw className="w-3.5 h-3.5" /> 刷新</button>
      </div>
      <Section title="本地历史库" testid="history-coverage" extra={<Database className="w-4 h-4 text-blue-300" />}>
        <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
          <Stat label="已覆盖股票" value={cov.n ?? "—"} sub={`失败 ${cov.failed ?? 0}`} />
          <Stat label="平均覆盖年限" value={cov.avg_years ? `${cov.avg_years.toFixed(1)} 年` : "—"} />
          <Stat label="≥8 年 / ≥5 年" value={`${cov.ge8 ?? 0} / ${cov.ge5 ?? 0}`} />
          <Stat label="日线总数" value={cov.bars ? cov.bars.toLocaleString() : "—"} />
          <Stat label="最新日期" value={cov.last_date || "—"} sub={(ds?.history_by_source || []).map((s) => `${s.source} ${s.n}`).join(" · ")} />
        </div>
      </Section>
      <Section title="后台任务" testid="jobs-section">
        <JobRow type="backfill" job={ds?.backfill_job} onRun={() => run("/data/backfill?mode=incremental", "历史库增量更新")} runLabel="增量更新" />
        <JobRow type="train" job={ms?.train_job} onRun={() => run("/models/train", "模型训练")} runLabel="重新训练" />
        <JobRow type="research" job={ms?.research_job} onRun={() => run("/research/run", "第二版训练与滚动回测")} runLabel="运行（3–6 小时）" />
      </Section>
      <ModelV3Panel />
      <ModelV2Report />
      <WalkForwardReport />
      <Section title={`当前模型 ${ms?.active_version || "（尚未训练）"}`} testid="model-section">
        {ens ? (
          <div className="space-y-5 text-xs text-slate-400">
            <div className="grid md:grid-cols-3 gap-4">
              <div>训练区间 <span className="font-num text-slate-200">{ens.model_parameters.split?.train?.join(" ~ ") || "—"}</span></div>
              <div>{ens.model_parameters.split?.valid ? "验证区间" : "校准区间"} <span className="font-num text-slate-200">{(ens.model_parameters.split?.valid || ens.model_parameters.split?.calib)?.join(" ~ ") || "—"}</span></div>
              <div>测试区间 <span className="font-num text-slate-200">{ens.model_parameters.split?.test?.join(" ~ ") || "—"}</span></div>
            </div>
            {ens.model_parameters.split?.rows && <div>样本：训练 {ens.model_parameters.split.rows.train.toLocaleString()} · 验证 {ens.model_parameters.split.rows.valid.toLocaleString()} · 测试 {ens.model_parameters.split.rows.test.toLocaleString()}（{ens.model_parameters.split.stocks} 只股票，每 {ens.model_parameters.split.stride} 个交易日采样，间隔 {ens.model_parameters.split.gap_days} 日防泄漏）</div>}
            {Object.keys(ens.model_parameters.weights || {}).map((h) => (
              <div key={h}>集成权重（{h}日）：{Object.entries(ens.model_parameters.weights[h] || {}).map(([k, v]) => `${k} ${(v * 100).toFixed(0)}%`).join(" · ")}</div>
            ))}
            {qm && <div>下一交易日价格区间（测试期）：80% 区间实际覆盖率 <b className="font-num text-slate-200">{pct(qm.close_80pct_interval_coverage, 1)}</b> · 中位数平均绝对误差 <b className="font-num text-slate-200">{pct(qm.close_median_mae, 2)}</b></div>}
            <div>PyTorch 时序模型：{ms.pytorch?.note || "—"}</div>
          </div>
        ) : <p className="text-sm text-slate-400">历史库建成后会自动训练 XGBoost、LightGBM 与 Scikit-learn 模型。</p>}
      </Section>
      <Section title="第一版回测（原样保留，用于前后对比）" testid="backtest-section"><Backtest bt={bt} /></Section>
      <Section title="数据源运行状态" testid="sources-section">
        <div className="overflow-x-auto">
          <table className="w-full text-xs min-w-[560px]">
            <thead className="text-slate-500 text-left"><tr><th className="py-1.5">数据源</th><th>接口</th><th>状态</th><th>行数</th><th>耗时</th><th>时间</th><th>错误</th></tr></thead>
            <tbody>{(ds?.sources || []).map((s) => (
              <tr key={s.id} className="border-t border-[#1E2838]"><td className="py-1.5">{s.source}</td><td>{s.endpoint}</td>
                <td className={s.ok ? "up" : "text-amber-300"}>{s.ok ? "正常" : "失败"}</td><td className="font-num">{s.rows}</td><td className="font-num">{s.elapsed}s</td>
                <td className="font-num">{dt(s.checked_at)}</td><td className="text-slate-500 max-w-[280px] truncate" title={s.error}>{s.error}</td></tr>
            ))}</tbody>
          </table>
        </div>
        <p className="text-[11px] text-slate-500 mt-3">{ds?.licenses_note}</p>
      </Section>
    </div>
  );
}
