export const isNum = (x) => typeof x === "number" && !Number.isNaN(x);
export const price = (x) => (isNum(x) ? x.toFixed(2) : "—");
export const pct = (x, d = 1, signed = false) =>
  isNum(x) ? `${signed && x > 0 ? "+" : ""}${(x * 100).toFixed(d)}%` : "—";
export const pctRaw = (x, d = 2) => (isNum(x) ? `${x > 0 ? "+" : ""}${x.toFixed(d)}%` : "—");
export const money = (x) => {
  if (!isNum(x)) return "—";
  if (Math.abs(x) >= 1e8) return `${(x / 1e8).toFixed(2)} 亿`;
  if (Math.abs(x) >= 1e4) return `${(x / 1e4).toFixed(2)} 万`;
  return x.toFixed(2);
};
export const yuan = (x) => (isNum(x) ? `¥${x.toLocaleString("zh-CN", { maximumFractionDigits: 2 })}` : "—");
export const tclass = (x) => (!isNum(x) || x === 0 ? "flat" : x > 0 ? "up" : "down");
export const dt = (s) => (s ? String(s).replace("T", " ").replace("+08:00", "").slice(0, 19) : "—");
export const score = (x) => (isNum(x) ? x.toFixed(0) : "—");

